const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_5","ls":"6.5","title":"Lernpfadübung · LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_5_Werbeaktion_planen.md"};
const COMP=[["Fachkompetenz","Ich vereinbare mit zwei Handelspartnern ein Werbeziel, das wir überprüfen können. Ich stimme passende Werbeträger und feste Termine ab. Ich kläre, welche Aufgaben der Großhandel und welche die beiden Läden übernehmen."],["Personalkompetenz","Ich habe die Fristen im Blick und prüfe, ob ich meine Zusagen einhalten kann."],["Sozialkompetenz","Ich höre, was den Beteiligten wichtig ist. Ich helfe, feste Absprachen zu finden."],["Methodenkompetenz","Ich halte Ziel, Maßnahmen und Termine in einem gemeinsamen Plan fest."],["Medienkompetenz","Ich wähle einen Werbeträger, der die gewünschte Kundschaft am jeweiligen Standort erreicht."]];
const BANK=[{"title":"Werbung für Block","scene":"Das 2-Rad Center Block ist ein Fahrradgeschäft in Aurich. Viele Kundinnen und Kunden fahren im Alltag Rad und kommen nach der Arbeit zur Beratung.","ask":"Was passt laut M1 zur Kundschaft von Block?","options":["Ein Newsletter kann Menschen erreichen, die schon Kontakt zu Block hatten.","Kundschaft aus dem Alltag ist für Block unwichtig.","Ein Hinweis vor dem Besuch kann zur Beratung einladen.","Die meisten angesprochenen Personen kommen laut M1 erst am Samstag.","Der Aufsteller in Leer erreicht Blocks Newsletter-Empfänger direkt.","Block möchte nur Verkäufe beobachten und zählt keine Beratungen."],"answer":[0,2],"why":"Der Newsletter erreicht bereits bekannte Kundschaft und kann zu persönlicher Beratung im Laden einladen. Block kann Beratungen zusätzlich zählen.","hint":"Prüfe, wann und weshalb die Menschen zu Block kommen.","steps":"Lies Blocks Zeile in M1. Unterscheide Kontakt vor dem Besuch und Kontakt im Laden.","example":"Eine Nachricht am Morgen kann auf einen Besuch nach der Arbeit vorbereiten.","c":4,"sourceRefs":["M1","M4"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Werbung in Leer","scene":"Die Bike Arena Oltmanns ist ein Fahrradgeschäft in Leer. Im Fall wählen viele Menschen das Zubehör auf einer Aktionsfläche selbst aus.","ask":"Welche Aussagen über die Zielgruppe und den Standort treffen zu?","options":["Fast alle Interessierten brauchen zuerst einen persönlichen Beratungstermin.","Familien und Menschen, die in der Freizeit Rad fahren, sind wichtige Zielgruppen.","Vor allem am Samstag kommen Familien in die Bike Arena.","Der Newsletter von Block ist der vorgesehene Werbeträger für Leer.","Die geplante Aktionsfläche richtet sich nur an Kundschaft, die schon bestellt hat.","Am Eingang oder Hauptgang lassen sich Menschen beim Einkauf auf die Aktion aufmerksam machen."],"answer":[1,2,5],"why":"Samstag ist für Familien besonders wichtig. Eingang und Hauptgang sind im Fall gut besuchte Werbeplätze, von denen Kundschaft zur Auswahlfläche gelangen kann.","hint":"Achte auf die Besuchszeit und die Plätze im Laden.","steps":"Vergleiche die Zeile der Bike Arena in M1 mit ihrer Stimme in M4.","example":"Ein Hinweis am Eingang kann eine Familie erreichen, bevor sie an Regalen vorbeigeht.","c":4,"sourceRefs":["M1","M4"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Werbeträger und Werbemittel","scene":"In M3 steht für jeden Werbeplatz auch die dazu passende gestaltete Werbung.","ask":"Welche Zuordnungen stimmen?","options":["Der fertige Werbebeitrag ist der Werbeträger für den E-Mail-Versand.","Das gedruckte Schild ist ein Werbemittel.","Ein Newsletter kann einen Werbebeitrag als Werbeträger verbreiten.","Der Aufsteller am Eingang ist das bedruckte Werbemittel selbst.","Das Schaufenster kann als Werbeträger für einen Aushang dienen.","Der Hauptgang ist der Einsatztermin des Schildes."],"answer":[1,2,4],"why":"Werbeträger verbreiten die Werbung oder geben ihr einen Platz. Ein Textbeitrag, ein Aushang oder ein bedrucktes Schild ist das gestaltete Werbemittel.","hint":"Frage zweimal: Was wird gestaltet? Wo erscheint es?","steps":"Markiere in M3 zuerst den Platz oder das Medium, dann das gestaltete Stück Werbung.","example":"Ein Plakatrahmen trägt das Plakat, das darin zu sehen ist.","c":4,"sourceRefs":["M3","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ziel oder Wunsch?","scene":"Jan Richter will vor dem Start wissen, woran beide Geschäfte erkennen, ob die Frühjahrsaktion ihr Ziel erreicht.","ask":"Welche Bausteine braucht ein überprüfbares Werbeziel?","options":["Eine Kennzahl, die beide Standorte erfassen können.","Einen Zielwert, den die Beteiligten vorher abstimmen.","Eine Aussage, dass beide Geschäfte mehr Aufmerksamkeit wollen.","Die technische Druckauflösung der Werbemittel.","Einen Zeitraum für die Messung.","Den Namen der zuletzt zuständigen Druckerei."],"answer":[0,1,4],"why":"Ein überprüfbares Ziel legt fest, was gemessen wird, welcher Wert erreicht werden soll und für welchen Zeitraum dieser Wert gilt.","hint":"Überlege, worüber Jan nach der Aktion entscheiden können soll.","steps":"Prüfe bei jedem Vorschlag: Hilft die Angabe zu entscheiden, ob das Ziel erreicht wurde?","example":"Ein Zielwert von 50 Stück ist erst mit Produktgruppe und Zeitraum eindeutig.","c":0,"sourceRefs":["M2","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Kennzahl für beide","scene":"Block möchte Beratungen zählen. Die Bike Arena möchte Verkäufe zählen und hat im Fall keine verlässlichen Beratungszahlen.","ask":"Welche Folgerungen sind für das gemeinsame Ziel sinnvoll?","options":["Beratungen bei Block und Stückzahlen in Leer lassen sich als dieselbe Kennzahl addieren.","Die Läden können die verkauften Stücke des Aktionssortiments einheitlich zählen.","Die Bike Arena kann fehlende Beratungszahlen einfach schätzen.","Block darf seine Beratungszahlen zusätzlich für den eigenen Laden betrachten.","Die Öffnungszeiten allein reichen als Kennzahl für den Verkaufserfolg.","Der Umsatz aller Warengruppen ist laut M2 die vereinbarte Kennzahl."],"answer":[1,3],"why":"Verkaufte Aktionsartikel sind für beide Läden verfügbar. Beratungszahlen helfen Block bei einer eigenen Frage, tragen aber keinen gemeinsamen Vergleich.","hint":"Beide Läden müssen dieselbe Größe erfassen können.","steps":"Stell die vorhandenen Daten beider Standorte nebeneinander. Prüfe, welche Messgröße in beiden Spalten steht.","example":"Verkaufte Stücke und geführte Beratungen sind zwei verschiedene Größen.","c":0,"sourceRefs":["Handlungssituation","M2"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ausgangszahlen","scene":"Jan will die Verkäufe der Aktionswoche mit einer früheren Woche vergleichen.","ask":"Welche Angaben gehören zur Ausgangslage aus M2?","options":["Block verkaufte 60 Stück aus dem Aktionssortiment.","Die Bike Arena verkaufte 60 Stück aus dem Aktionssortiment.","Block verkaufte 40 Stück aus dem Aktionssortiment.","Die Zahl 40 bezeichnet die Beratungen bei Block.","Die früheren Stückzahlen sind bereits die Werte der Aktionswoche.","Beide Läden hatten in der Vergleichswoche an denselben Tagen geöffnet."],"answer":[1,2,5],"why":"Die Ausgangswerte sind 40 Stück bei Block und 60 Stück in der Bike Arena. Gleiche Öffnungstage machen die Wochen vergleichbarer.","hint":"Lies die Zahlen zusammen mit ihrem Zeitraum und ihrer Einheit.","steps":"Schreib für beide Standorte die Stückzahl auf. Prüfe dann die Öffnungstage im gleichen Absatz.","example":"40 Stück sind eine Absatzmenge. 40 Kundengespräche wären eine andere Größe.","c":3,"sourceRefs":["M2","M4"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Newsletter im Kalender","scene":"Block möchte mit seinem E-Mail-Newsletter zur Beratung einladen.","ask":"Welche Angaben gehören in den Terminplan für diesen Newsletter?","options":["Die Ladenleitung genehmigt den Text bis Donnerstag um 12 Uhr in der Vorbereitungswoche.","Die Druckerei genehmigt und verschickt den Newsletter.","Block verschickt den Newsletter am Montag um 8 Uhr vor dem Verkaufsstart.","Die Freigabe ist erst am Montag nach dem Verschicken fällig.","Der Newsletter ersetzt die Meldung der Verkaufszahlen.","Block plant und verschickt den Newsletter selbst."],"answer":[0,2,5],"why":"Die Ladenleitung von Block gibt den Beitrag bis Donnerstagmittag frei. Block versendet ihn am folgenden Montagmorgen, bevor der Verkauf am Dienstag beginnt.","hint":"Lies die Newsletter-Zeile in M3 bis zum Ende.","steps":"Teile die Zeile in drei Fragen auf: Wer gibt frei, bis wann und wann erscheint der Beitrag?","example":"Ein Newsletter kann vor dem ersten Verkaufstag ankündigen, was ab Dienstag erhältlich ist.","c":1,"sourceRefs":["M3"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eingangsschild in Leer","scene":"Die Bike Arena hat einen Platz für den Aufsteller am Eingang eingeplant.","ask":"Welche Angaben müssen für diesen Aufsteller stimmen?","options":["Freigabe bis Freitag um 12 Uhr, weil die Bike Arena das Eingangsschild selbst druckt.","Die Bike Arena meldet der Druckerei die Freigabe bis Mittwoch um 16 Uhr.","Die Druckerei liefert bis Donnerstag der Aktionswoche.","Global Bike stellt das Schild am Montag am Eingang auf.","Das bedruckte Schild steht ab Freitag der Aktionswoche am Eingang.","Die Materiallieferung durch Sarah ersetzt die Druckfreigabe."],"answer":[1,2,4],"why":"Für den Eingang ist die Druckerei eingeplant. Die Bike Arena erteilt ihr am Mittwoch bis 16 Uhr die Freigabe. Nach der Lieferung stellt der Laden das Schild ab Freitag auf.","hint":"Unterscheide den Eingang vom Werbeplatz am Hauptgang.","steps":"Folge der Zeile für den Aufsteller am Eingang von Druckfreigabe über Lieferung bis zum Einsatz.","example":"Ein Schild kann einen Tag vor dem Aufstellen geliefert werden.","c":1,"sourceRefs":["M3","M4"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zusammenarbeit planen","scene":"Global Bike und zwei Fahrradgeschäfte planen eine gemeinsame Frühjahrsaktion.","ask":"Woran erkennt man kooperative Werbung in diesem Fall?","options":["Alle drei Partner vereinbaren ein gemeinsames Ziel.","Die Druckerei legt die Verkaufsziele und die Produkte fest.","Jeder Laden veröffentlicht ohne Abstimmung seine eigene Aktion.","Global Bike liefert Produktangaben, die Läden prüfen ihre jeweilige Fassung.","Beide Standorte müssen dasselbe Werbemittel nutzen, damit es eine Kooperation ist.","Die Läden stimmen Aufgaben und Fristen mit Global Bike ab."],"answer":[0,3,5],"why":"Ein gemeinsames Ziel, abgestimmte Aufgaben und eigene Beiträge der Partner kennzeichnen die Zusammenarbeit. Die Werbemittel dürfen zum jeweiligen Standort passen.","hint":"Schau, welche Beiträge sich zwischen den Partnern ergänzen.","steps":"Notiere je Partner einen Beitrag. Prüfe, ob die Beteiligten ein gemeinsames Ergebnis vorbereiten.","example":"Eine gemeinsame Aktion kann an einem Standort per Nachricht und am anderen per Schild angekündigt werden.","c":2,"sourceRefs":["M3","M6"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Freigabe und Einsatz","scene":"In dem Werbeplan stehen eine Freigabefrist und ein Einsatztermin.","ask":"Welche Erklärungen helfen den Beteiligten, die beiden Angaben auseinanderzuhalten?","options":["Der Einsatztermin gibt an, wann Kundinnen und Kunden die Werbung sehen können.","Die Freigabefrist nennt den spätesten Zeitpunkt für die Zustimmung.","Beim Eingangsschild ersetzt der Tag des Aufstellens die Nachricht an die Druckerei.","Die Freigabefrist fällt grundsätzlich mit dem Ende der Aktion zusammen.","Die Werbung kann später erscheinen, als sie freigegeben wurde.","Der Einsatztermin gibt vor, wann die Verkaufszahlen gemeldet werden."],"answer":[0,1,4],"why":"Die Freigabe liegt so früh, dass Herstellung oder Versand noch möglich sind. Der Einsatztermin markiert, ab wann die Werbung sichtbar ist.","hint":"Frag bei jedem Datum, was an dem Tag tatsächlich passiert.","steps":"Nutze die Termine für den Aufsteller als Beispiel und ordne jeden einem Arbeitsschritt zu.","example":"Bei einem Druckauftrag liegt die Zustimmung für die Druckerei vor der Lieferung.","c":1,"sourceRefs":["M3","M6"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Aufgaben klar verteilen","scene":"Global Bike bereitet Daten und Entwürfe vor. Die Läden entscheiden über ihre Fassungen.","ask":"Welche Zuständigkeiten sind im Werbeplan richtig zugeordnet?","options":["Jan koordiniert bei Global Bike die Absprachen.","Sarah setzt beide Werbemittel selbst vor Ort ein.","Die Ladenleitungen prüfen die Angaben sowie den Platz und geben ihre jeweilige Fassung frei.","Die Druckerei meldet nach der Aktion die Kassenverkäufe aus Leer.","Block meldet für beide Läden die Gesamtzahlen ohne Rücksprache.","Sarah stellt am Mittwoch ab 10 Uhr Produktinformationen und Bilder bereit."],"answer":[0,2,5],"why":"Sarah liefert die Unterlagen, Jan koordiniert und jede Ladenleitung verantwortet die eigene Freigabe. Die Läden melden ihre Verkäufe jeweils selbst.","hint":"Trenne Koordination, Vorbereitung, Freigabe und Rückmeldung.","steps":"Gehe in M3 nacheinander Sarahs, Jans und die Aufgaben der Ladenleitungen durch.","example":"Wer einen Entwurf liefert, erteilt damit noch keine Freigabe für einen Laden.","c":2,"sourceRefs":["M3","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Erfolg nachsehen","scene":"In M2 ist der Montag nach der Frühjahrsaktion für die Meldung der Ergebnisse vorgesehen.","ask":"Welche Informationen braucht Global Bike für die Erfolgskontrolle?","options":["Die in der Aktionswoche verkauften Stücke je Laden.","Die Namen aller Personen, die ein Fahrradgeschäft besucht haben.","Die vereinbarten Zielwerte und passenden Ausgangsmengen.","Die Werbemaßnahme, die der anderen Niederlassung am besten gefallen hat.","Die Beratungen von Block als Ersatz für fehlende Stückzahlen.","Information darüber, auf welche Woche die Zahlen sich beziehen."],"answer":[0,2,5],"why":"Ausgangswert, Zielwert, gemessene Stückzahl und der passende Zeitraum machen die Kontrolle möglich. Die Läden melden ihre Stückzahlen getrennt.","hint":"Denk an die Daten, die sich nach der Aktion mit dem Plan vergleichen lassen.","steps":"Notiere in einer Zeile je Laden Altwert, Ziel, Aktionswert und Zeitraum.","example":"Eine Gesamtzahl ohne Standort oder Woche reicht für getrennte Ladenvergleiche nicht.","c":3,"sourceRefs":["M2","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Machbares gemeinsames Ziel","scene":"Aus M2: Block verkaufte in der Vergleichswoche 40, die Bike Arena 60 Stück aus dem Aktionssortiment.","ask":"Welche Vorschläge sind als gemeinsames Werbeziel vollständig und mit M2 überprüfbar?","options":["In beiden Läden soll die Frühjahrsaktion gut ankommen.","In der Aktionswoche sollen aus dem Aktionssortiment bei Block mindestens 44 und in der Bike Arena mindestens 66 Stück verkauft werden.","Beide Läden sollen im Frühjahr ungefähr zehn mehr erreichen.","Der Newsletter soll in der Vorbereitungswoche bis Donnerstag freigegeben sein.","In der Aktionswoche sollen die Verkäufe der Aktionsartikel bei beiden Läden um mindestens 10 % über der Vergleichswoche liegen.","Die Läden sollen in der Aktionswoche jeweils mindestens 20 Kundengespräche führen und für das gemeinsame Ergebnis erfassen."],"answer":[1,4],"why":"44 und 66 Stück sind die Zielwerte bei jeweils 10 % Zuwachs. Beide Formulierungen nennen eine messbare Größe, ihren Zielwert und den passenden Zeitraum.","hint":"Suche jede der drei Angaben und prüfe, ob beide Läden die Zahl haben.","steps":"Unterstreiche in jeder Formulierung, was, wie viel und wann gemessen wird. Gleiche es mit M2 ab.","example":"Ein Versandtermin ist überprüfbar, beantwortet aber nicht die gewünschte Frage nach der Verkaufsentwicklung.","c":0,"sourceRefs":["M2","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Von Prozent zu Stück","scene":"Übungsvariante: Die Partner wollen in jedem Laden mindestens 15 % mehr aus dem Aktionssortiment verkaufen als in der Vergleichswoche.","ask":"Welche Einträge im Plan stimmen rechnerisch oder helfen bei der späteren Kontrolle?","options":["Block: mindestens 46 Stück.","Bike Arena: mindestens 65 Stück.","Block: mindestens 55 Stück, weil 15 % gleich 15 Stück sind.","Bike Arena: mindestens 69 Stück.","Als Ausgangswerte 40 und 60 Stück getrennt aufschreiben.","Die Zielwerte sind 6 und 9 Stück insgesamt, weil nur der Zuwachs zählt."],"answer":[0,3,4],"why":"15 % von 40 sind 6, 15 % von 60 sind 9. Die Zielwerte sind 46 und 69 Stück. Die getrennten Ausgangswerte gehören zur Erfolgskontrolle.","hint":"Rechne pro Laden zuerst den Zuwachs und danach den Zielwert.","steps":"Multipliziere jede Ausgangsmenge mit 0,15 und addiere das Ergebnis zu dieser Ausgangsmenge.","example":"Bei 20 Stück Ausgangsmenge ergeben 15 % Zuwachs insgesamt 23 Stück.","c":3,"sourceRefs":["M2","M5"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vor dem Besuch oder im Laden","scene":"Übungsvariante: Block will seine bekannte Kundschaft vor dem Ladenbesuch zur Beratung einladen. Die Bike Arena möchte am Samstag Menschen gleich beim Betreten erreichen.","ask":"Welche beiden Plätze erfüllen diese Absichten in M3 am direktesten?","options":["Block: Aushang im Schaufenster ab Dienstag, der am besten beim Vorbeigehen wirkt.","Bike Arena: erst am Montag nach der Aktion über das Schild berichten.","Block: Versand des E-Mail-Newsletters am Montag um 8 Uhr.","Bike Arena: Aufsteller am Eingang ab Freitag, also auch am Samstag.","Bike Arena: Schild am Hauptgang, auch wenn ausdrücklich der erste Eindruck am Eingang zählen soll.","Block: erst am Samstag einen Hinweis in der Bike Arena aufstellen."],"answer":[2,3],"why":"Der Newsletter erreicht bekannte Kundschaft vor dem Besuch. Der Aufsteller steht am Samstag schon am Eingang der Bike Arena und erreicht dort die ankommenden Menschen.","hint":"Überlege, an welcher Stelle im Weg der Kundschaft die Werbung ankommen soll.","steps":"Markiere die beiden Zeitpunkte: vor dem Besuch und beim Betreten. Vergleiche beide mit M1 und M3.","example":"Ein Aushang wirkt erst dort, wo Menschen an ihm vorbeikommen.","c":4,"sourceRefs":["M1","M3"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Aufsteller rechtzeitig vorbereiten","scene":"Sarah kann der Bike Arena bis Mittwoch um 14 Uhr ihren Entwurf schicken. Die Druckerei braucht die Freigabe bis 16 Uhr.","ask":"Was muss Jan in dem verbleibenden Zeitfenster abstimmen?","options":["Die Ladenleitung der Bike Arena ist zwischen Entwurf und Freigabefrist ansprechbar.","Die Druckerei soll das Schild schon vor der Freigabe fertig drucken.","Die Ladenleitung hat Zeit, Platz und Produktangaben zu prüfen.","Global Bike gibt ohne Ladenleitung den Entwurf als verbindlich aus.","Die Ladenleitung meldet ihre Freigabe bis 16 Uhr an die Druckerei.","Die Freigabe kann wegen des Einsatzes am Freitag der Aktionswoche erst dann erfolgen."],"answer":[0,2,4],"why":"Zwischen 14 und 16 Uhr bleiben höchstens zwei Stunden für Prüfung und Rückmeldung der Ladenleitung. Die Druckerei muss ihre Freigabe in diesem Fenster erhalten.","hint":"Ordne die Frist der Prüfung zu, die ihr vorausgehen muss.","steps":"Markiere 14 Uhr und 16 Uhr auf einer Zeitachse und setze die Prüfung und die Meldung dazwischen.","example":"Einen Termin einzuplanen hilft erst, wenn die zuständige Person in dem Zeitfenster verfügbar ist.","c":1,"sourceRefs":["M3","M4"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Wechsel zum Hauptgang","scene":"Übungsvariante: Die Bike Arena verpasst die Mittwochsfrist für den Aufsteller am Eingang. Die Möglichkeit am Hauptgang aus M3 ist noch verfügbar.","ask":"Welche Änderungen gehören in die neue Planzeile?","options":["Auf den Werbeplatz am Hauptgang mit einem gedruckten Hinweisschild wechseln.","Den Eingangstermin Freitag unverändert übernehmen, obwohl das Hauptgangschild früher bereitstehen kann.","Die Freigabe der Bike Arena bis Freitag um 12 Uhr in der Vorbereitungswoche eintragen.","Die Druckerei für das Hauptgangschild verpflichtend erneut beauftragen.","Die Bike Arena druckt das Schild selbst und bringt es zur Öffnung am Dienstag an.","Die gemeinsame Kennzahl bei diesem Wechsel automatisch von Absatz auf Beratungszahl ändern."],"answer":[0,2,4],"why":"Für den Hauptgang gelten ein anderer Platz, eigener Druck, Freigabe bis Freitagmittag und Einsatz ab Dienstag zur Öffnung. Das gemeinsame Verkaufsziel bleibt bei einem Wechsel des Platzes vergleichbar.","hint":"Vergleiche beide Werbeplätze in M3 Zeile für Zeile.","steps":"Streiche nur die alten Eingangsschritte. Übertrage die Termine und Zuständigkeiten des Hauptgangschilds.","example":"Ein geänderter Werbeplatz verlangt eine neue Zeitachse, aber keine neue Kennzahl, solange das Ziel gleich bleibt.","c":3,"sourceRefs":["M2","M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zusagen sauber festhalten","scene":"Übungsvariante: Im Gespräch sagen die beiden Ladenleitungen, dass ihre Fristen eingehalten werden können, wenn die Entwürfe am Mittwoch um 14 Uhr da sind.","ask":"Welche Formulierungen könnte Jan direkt in eine Gesprächsnotiz übernehmen?","options":["Die Ladenleitung der Bike Arena prüft das Eingangsschild und meldet der Druckerei ihre Freigabe bis Mittwoch 16 Uhr.","Beide Läden kümmern sich irgendwann um alles Nötige.","Global Bike schickt bis Mittwoch 14 Uhr je einen Entwurf an beide Ladenleitungen.","Sarah prüft nebenbei, ob irgendwann ein Platz frei ist.","Block gibt den Newsletter-Text durch seine Ladenleitung bis Donnerstag 12 Uhr frei und versendet Montag 8 Uhr.","Die Ladenzusagen brauchen keinen Zeitpunkt, da beide im Gespräch zugestimmt haben."],"answer":[0,2,4],"why":"Verbindliche Absprachen nennen Verantwortliche, Handlung und Termin. So erkennen alle, was sie bis wann zusagen und wer auf die Erledigung wartet.","hint":"Achte auf drei Angaben: wer, was und bis wann.","steps":"Prüfe jede Formulierung mit diesen drei Fragen. Markiere leere oder unklare Angaben.","example":"„Drucken“ reicht nicht, wenn weder klar ist, wer druckt, noch bis wann.","c":2,"sourceRefs":["M3","M4","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Interessen unterbringen","scene":"Block möchte Beratungen sichtbar machen. Die Bike Arena kann nur die verkauften Stücke verlässlich erfassen.","ask":"Welche Vereinbarungen berücksichtigen beide Interessen?","options":["Für die gemeinsame Auswertung zählen beide die verkauften Stücke aus dem Aktionssortiment.","Block meldet seine Beratungen zusätzlich und kennzeichnet sie als eigene Standortzahl.","Block darf im Newsletter keine Beratung erwähnen, solange diese nicht die gemeinsame Kennzahl ist.","Leer schätzt die Beratungen anhand der Familienzahl und meldet sie als echte Werte.","Die Partner legen vorab fest, welche Zahlen für das gemeinsame Ziel gelten und welche Zusatzdaten sind.","Sie geben einen gemeinsamen Prozentwert an, indem sie Beratungen und Stückzahlen zusammenzählen."],"answer":[0,1,4],"why":"Die gemeinsame Messung bleibt einheitlich. Block kann gleichzeitig sein Beratungsinteresse verfolgen und die Zahl getrennt ausweisen.","hint":"Ein gemeinsames Ziel und ein zusätzlicher Ladenwert können nebeneinanderstehen.","steps":"Formuliere eine Abmachung für beide und eine ergänzende Abmachung nur für Block.","example":"Ein Laden kann Gespräche für sich auswerten, ohne sie in einen Vergleich von Stückzahlen zu mischen.","c":2,"sourceRefs":["Handlungssituation","M1","M2"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Passender Aushang","scene":"Übungsvariante: Block entscheidet sich für das Schaufenster, um Menschen direkt vor Ort auf die Aktion hinzuweisen.","ask":"Welche Einträge passen zu diesem Beschluss?","options":["Werbeträger: der gedruckte Aushang. Werbemittel: das Schaufenster.","Freigabe und Ausdruck bis Freitag um 14 Uhr in der Vorbereitungswoche.","Block versendet den Schaufensterhinweis am Montag um 8 Uhr als Newsletter.","Werbeträger: das Schaufenster. Werbemittel: der gedruckte Aushang.","Der Aushang kann beim Vorbeigehen auf Zubehör und Beratung aufmerksam machen.","Der Aushang ersetzt die Stückzahlmeldung am Montag nach der Aktion."],"answer":[1,3,4],"why":"Das Schaufenster ist der Platz, der Aushang die gestaltete Werbung. Block gibt ihn bis Freitag um 14 Uhr frei, druckt ihn und bringt ihn ab Dienstag zur Öffnung an.","hint":"Nimm in M3 ausdrücklich die Schaufenster-Zeile.","steps":"Ordne Platz, Werbung, Vorteil und Termine der richtigen Zeile zu.","example":"Ein Aushang kann vor Ort ansprechbar machen, was später persönlich beraten wird.","c":4,"sourceRefs":["M1","M3"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zahlen ohne Verwechslung melden","scene":"Übungsvariante: Block zählt in der Aktionswoche 48 verkaufte Stücke und 35 Beratungen. Die Bike Arena verkauft 62 Stück.","ask":"Welche Meldungen sind für die gemeinsame Erfolgskontrolle brauchbar?","options":["Block meldet 35 Beratungen als gemeinsamen Aktionswert.","Block meldet 48 Stück des Aktionssortiments.","Die Bike Arena meldet 62 Stück des Aktionssortiments.","Global Bike erhält nur 145 als Summe aus Verkäufen und Beratungen.","Die Zahlen werden am Montag nach der Aktion gemeldet, mit Standort und Zeitraum.","Die Vergleichswoche wird künftig mit 48 und 62 Stück angegeben."],"answer":[1,2,4],"why":"Für das gemeinsame Ziel zählen 48 und 62 verkaufte Stücke aus der Aktionswoche. Die 35 Beratungen können getrennt bleiben. Die früheren Vergleichswerte ändern sich nicht.","hint":"Kreise die Zahlen ein, die dieselbe Einheit haben.","steps":"Ordne jede Zahl einer Tätigkeit und einer Woche zu. Übernimm nur die passenden Stückzahlen.","example":"Eine zusätzliche Kennzahl wird nicht Teil der gemeinsamen Zahl, bloß weil sie in derselben Nachricht steht.","c":3,"sourceRefs":["M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zielerreichung vergleichen","scene":"Übungsvariante: Ziel sind jeweils mindestens 10 % mehr verkaufte Aktionsartikel. Block meldet 44 und die Bike Arena 64 Stück. Ausgangswerte: 40 und 60.","ask":"Welche Aussagen stimmen?","options":["Block hat exakt 10 % mehr verkauft und damit sein Ziel erreicht.","Die Bike Arena hat ebenfalls exakt 10 % mehr verkauft, weil beide vier Stück mehr verkauft haben.","Die Bike Arena brauchte mindestens 66 Stück und verfehlt ihr Ziel um zwei Stück.","Beide Läden haben das Ziel allein deshalb erreicht, weil beide Mengen gestiegen sind.","Nur die Bike Arena hat das Ziel erreicht, weil sie insgesamt mehr verkauft hat.","Die Veränderung wird jeweils am eigenen Ausgangswert des Ladens gemessen."],"answer":[0,2,5],"why":"Vier zusätzliche Stücke entsprechen bei 40 Stück genau 10 %, bei 60 Stück rund 6,7 %. Deshalb erreicht Block das jeweilige Ziel, die Bike Arena noch nicht.","hint":"Der Prozentzuwachs hängt von der Ausgangsmenge ab.","steps":"Berechne zuerst 10 % der 40 bzw. 60 Stück. Vergleiche für jeden Laden Ist und Ziel.","example":"Vier zusätzliche Stücke auf 20 entsprechen 20 %, auf 40 nur 10 %.","c":0,"sourceRefs":["M2","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen Anstieg einordnen","scene":"Übungsvariante: Beim Treffen nach der Aktion sind die Verkäufe gegenüber der Vergleichswoche in beiden Läden gestiegen.","ask":"Welche Auswertung kann Jan fachlich vertreten?","options":["Die gemessenen Stückzahlen mit den vereinbarten Zielwerten vergleichen.","Aus dem Anstieg allein schließen, dass die Werbung ihn vollständig verursacht hat.","Weitere mögliche Einflüsse im Bericht offenlassen.","Für beide Verkaufsergebnisse die Stückzahlen derselben Warengruppe und vergleichbarer Öffnungstage prüfen.","Den späteren Versandtermin als Nachweis für die Werbewirkung ausgeben.","Die Kennzahl nachträglich austauschen, falls ein Geschäft das Ziel verfehlt."],"answer":[0,2,3],"why":"Die Zahlen zeigen, wie die Läden zum Ziel stehen. Auch andere Einflüsse können Verkäufe verändern. Deshalb gehören eine saubere Abgrenzung und eine vorsichtige Deutung in den Bericht.","hint":"Trenne Ergebnis und Erklärung für das Ergebnis.","steps":"Schreibe für eine Rückmeldung zuerst den messbaren Vergleich auf und danach, was daraus offenbleibt.","example":"Ein Verkaufsanstieg kann mit einer gelungenen Werbung zusammenfallen, ohne ihre genaue Wirkung zu belegen.","c":0,"sourceRefs":["M2"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Freigabefähiger Plan","scene":"Übungsvariante: Ein Entwurf enthält für Block lediglich „Newsletter am Montag“ und für die Bike Arena „Aufsteller bei Gelegenheit“. Das gemeinsame Ziel ist schon vollständig formuliert.","ask":"Welche Ergänzungen sollte Jan vor der Freigabe verlangen?","options":["Für Block die zuständige Ladenleitung, ihre Frist und die Versandzeit festhalten.","Für den Aufsteller die Druckfreigabe, Drucklieferung und den Einsatztermin eintragen.","Die fertigen Werbemittel ersetzen alle Terminangaben im Plan.","Für beide Werbeplätze erklären, warum sie zur jeweiligen Kundschaft passen.","Als Erfolgskontrolle nur beide Werbemittel nebeneinander betrachten.","Die fehlenden Fristen erst nach Erscheinen der Werbung ergänzen."],"answer":[0,1,3],"why":"Ein freigabefähiger Werbeplan legt Gründe, Zuständigkeiten, Freigabe und Einsatz fest. Ein fertiger Entwurf allein klärt keine Abläufe.","hint":"Lies den knappen Entwurf so, als müsstest du ihn morgen ausführen.","steps":"Prüfe je Laden: Welche Person muss wann handeln, und warum ist dieser Werbeplatz vorgesehen?","example":"„Schild am Eingang ab Freitag“ sagt noch nicht, wann die Druckerei ihre Freigabe braucht.","c":1,"sourceRefs":["M1","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Das Treffen vorbereiten","scene":"Übungsvariante: Mittwoch vor der Frühjahrsaktion. Jan bittet dich, die Abstimmung zwischen Block und der Bike Arena zu leiten. Die Angaben in M1 bis M3 gelten weiterhin. Dein erster Schwerpunkt soll auch in deinen späteren Entscheidungen sichtbar bleiben.","ask":"Womit eröffnest du die Abstimmung?","options":["Du legst die bisherigen Stückzahlen und die verfügbaren Messdaten beider Läden nebeneinander.","Du fragst beide Ladenleitungen, was ihnen bei der Aktion besonders wichtig ist.","Du markierst die frühesten Fristen und die Personen, die für Freigaben zuständig sind.","Du trennst vergleichbare Verkaufsdaten von den zusätzlichen Beratungszahlen bei Block.","Du fasst die Wünsche zu Beratung und Selbstbedienung zusammen und lässt beide Läden sie ergänzen.","Du skizzierst die Arbeitsschritte vom Entwurf bis zum Einsatz und markierst, welche Zusagen noch fehlen."],"consequences":["Die beiden Ausgangswerte sind sichtbar. Diese Grundlage hilft euch beim Formulieren eines messbaren Ziels.","Die Ladenleitungen können ihre verschiedenen Erwartungen nennen, bevor sie eine Entscheidung treffen.","Die Druckfreigabe kann gleich im Gespräch mit den richtigen Verantwortlichen geklärt werden.","Du verhinderst, dass Beratung und Stückverkauf versehentlich in einen Messwert geraten.","Die unterschiedlichen Bedürfnisse beider Standorte bleiben für die Werbeauswahl sichtbar.","Der Ablauf zeigt, an welchen offenen Zusagen die spätere Umsetzung hängt."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Wähle einen Schwerpunkt für die Abstimmung. Alle drei Perspektiven gehören zum Plan.","steps":"Überlege, welche Information du in jedem späteren Schritt wieder nutzen möchtest.","example":"Ein Start bei den Ausgangsdaten kann später beim Ziel und bei der Erfolgskontrolle wieder aufgegriffen werden.","c":2,"sourceRefs":["Handlungssituation","M1","M2","M3"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Das Ziel vereinbaren","scene":"Die Beteiligten akzeptieren Stückzahlen als gemeinsame Kennzahl. Jetzt soll der Plan eindeutig sagen, wie der Erfolg je Laden beurteilt wird.","ask":"Wie bereitest du die Einigung über einen Zielwert vor?","options":["Du rechnest einen möglichen prozentualen Zuwachs getrennt für 40 und 60 Stück in absolute Zielmengen um.","Du besprichst die gewünschten Zuwächse mit beiden Ladenleitungen und klärst, welche Werte beide verbindlich mittragen.","Du legst verbindlich fest, welche Artikel, Tage und Kassenmeldungen in die gemeinsame Messung eingehen.","Du stellst zwei vollständige Ziele mit der gleichen Kennzahl und unterschiedlichen Zielwerten gegenüber.","Du hältst fest, welche eigene Kennzahl Block zusätzlich erfasst und wofür der gemeinsame Zielwert steht.","Du trägst Zielgrößen, Meldezeitpunkt und Verantwortung für die Erfassung in das gemeinsame Planblatt ein."],"consequences":["Die Zielmengen lassen sich später für jeden Laden mit der passenden Ausgangsmenge vergleichen.","Beide Ladenleitungen können einem konkreten Ziel zustimmen und wissen, worauf die gemeinsame Auswertung schaut.","Die Messung bekommt klare Grenzen, sodass beide Standorte dieselben Kriterien anwenden.","Die Beteiligten können die beiden Vorschläge vergleichen, ohne die Messmethode zu wechseln.","Block kann sein Beratungsinteresse berücksichtigen, während die gemeinsame Auswertung einheitlich bleibt.","Zur Zahl kommt eine gesicherte Zuständigkeit für die spätere Meldung hinzu."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Knüpfe an den Schwerpunkt deiner Eröffnung an und beachte die vorhandenen Zahlen.","steps":"Prüfe, welchen Aspekt dein Vorschlag für die gemeinsam vereinbarte Kennzahl besonders gut klärt.","example":"Dasselbe Plus in Stück kann bei zwei unterschiedlichen Ausgangswerten ein anderes prozentuales Plus bedeuten.","c":0,"sourceRefs":["M2","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Werbeplätze wählen","scene":"Für Block stehen Newsletter und Schaufenster zur Auswahl. Für die Bike Arena gibt es Aufsteller und Hauptgang. Alle im Plan genannten Plätze sind zum Zeitpunkt des Treffens noch möglich.","ask":"Wie begründest du die Auswahl je Standort?","options":["Du vergleichst die Werbeträger mit den dokumentierten Besuchszeiten und wählst pro Standort eine passende Möglichkeit.","Du lässt beide Ladenleitungen erklären, wo sie in ihrem Laden die gewünschte Kundschaft am besten erreichen.","Du legst die vier möglichen Werbeplätze samt Fristen auf die Zeitachse und klärst, bei welchen die Freigaben rechtzeitig klappen.","Du prüfst anhand der Ladenprofile, ob die Werbung vor dem Besuch, beim Ankommen oder erst im Laden wirken soll.","Du fragst nach den unterschiedlichen Wünschen zu Beratung und Orientierung und lässt sie als Begründung in die Standortzeilen aufnehmen.","Du klärst je Platz, wer den Druck oder Versand übernimmt und ob die dafür nötige Freigabe gesichert werden kann."],"consequences":["Besuchszeit und Ort der Ansprache sind als überprüfbare Gründe dokumentiert.","Die Auswahl passt zu dem Wissen, das die Ladenleitungen über Menschen und Abläufe vor Ort haben.","Vor der Auswahl ist sichtbar, welche Einsätze innerhalb der Vorbereitungsfrist möglich sind.","Du trennst verschiedene Zeitpunkte des Kontakts und kannst den Platz gezielt begründen.","Die Begründung hält die unterschiedlichen Bedürfnisse beider Standorte im Plan fest.","Die gewählten Plätze sind mit den zuständigen Personen und Arbeitsschritten verbunden."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Behalte die Zielgruppe im Blick. Entscheide, wie du die Auswahl im Plan belegst.","steps":"Ordne deinem bisherigen Schwerpunkt einen konkreten Prüfschritt in M1 oder M3 zu.","example":"Ein Newsletter und ein Aushang können dieselbe Botschaft an unterschiedlichen Punkten des Einkaufs zeigen.","c":4,"sourceRefs":["M1","M3","M4"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Einen Engpass bearbeiten","scene":"Übungsvariante: Die Bike Arena meldet kurz vor 16 Uhr, dass die Druckfreigabe für den Eingang nicht mehr rechtzeitig klappt. Der Werbeplatz am Hauptgang ist noch verfügbar.","ask":"Wie reagierst du, ohne die gemeinsame Aktion aus dem Blick zu verlieren?","options":["Du prüfst anhand von M3, ab wann das Hauptgangschild wirken kann und wodurch es die Zielgruppe im Laden erreicht.","Du fragst die Ladenleitung, wie sie Familien vom Eingang zur Fläche leiten kann, wenn der Hinweis am Hauptgang steht.","Du nimmst den nicht mehr erreichbaren Drucktermin aus dem Plan und setzt die Fristen für den Hauptgang ein.","Du hältst in der Planzeile fest, welche Annahme zur Erreichbarkeit nach dem Ortswechsel noch geprüft werden muss.","Du stimmst mit der Bike Arena und Sarah ab, wie sich der Ersatz im gemeinsamen Text und in der jeweiligen Ladenfassung zeigt.","Du sicherst die Freigabe der Bike Arena bis Freitag um 12 Uhr und klärst den eigenen Druck und Einsatz am Dienstag."],"consequences":["Der Ersatz ist mit einem konkreten Platz und einem Einsatztermin begründet.","Die Ladenleitung kann eine Wegführung vorschlagen, die unter den geänderten Bedingungen funktioniert.","Die Zeitachse zeigt nur noch Schritte, die der Laden tatsächlich ausführen kann.","Eine offene Annahme bleibt sichtbar, statt als erwiesene Wirkung in den Plan zu rutschen.","Die Botschaft lässt sich mit den Beteiligten anpassen, ohne die gemeinsame Aktion aufzugeben.","Die Bike Arena hat einen ausführbaren Ersatz mit Zuständigkeit und Frist."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Prüfe deine bisherige Entscheidung und welche Bedingungen sich geändert haben.","steps":"Streiche den verpassten Druckweg und prüfe die Ersatzmöglichkeit mit deinem Schwerpunkt.","example":"Bei einem Wechsel des Werbeplatzes ändern sich oft die Zuständigkeit und die Wirkung am jeweiligen Ort.","c":1,"sourceRefs":["M1","M3","M4"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Plan abstimmen","scene":"Newsletter für Block und ein Hinweisschild am Hauptgang in Leer sollen in die Endfassung. Jan will den Plan vor der Freigabe noch einmal prüfen lassen.","ask":"Wie machst du den Plan vor der Freigabe belastbar?","options":["Du prüfst für beide Standortzeilen, ob die Begründung und sämtliche Ist- und Zielwerte auf die richtigen Angaben in M1 bis M3 zurückgehen.","Du zeigst beiden Ladenleitungen ihre Planzeile und lässt sie Auftrag, Termine und Begründung bestätigen.","Du gehst Entwurf, Freigabe, Druck oder Versand und Einsatz in der Reihenfolge durch und ergänzt jede fehlende Verantwortung.","Du kontrollierst, dass Newsletter und Hauptgangschild zum jeweiligen Kontaktzeitpunkt passen und die Messgröße gleich bleibt.","Du klärst offen, ob sich eine Person mit ihrer Zusage übernommen hat, und hältst vereinbarte Änderungen fest.","Du ergänzt neben den Einsatzterminen eine Meldezeile für den Montag nach der Aktion und legst fest, wer für welchen Laden meldet."],"consequences":["Es ist nachvollziehbar, aus welchem Material die Begründungen und Planwerte stammen.","Die zugesagten Aufgaben sind mit den Personen abgestimmt, die sie tatsächlich ausführen.","Abhängigkeiten und noch offene Aufgaben lassen sich vor dem Einsatz erkennen.","Der Plan verbindet passende Werbeplätze mit einer gemeinsamen Auswertung.","Unklare Zusagen lassen sich rechtzeitig ändern und werden für alle sichtbar.","Die Erfolgskontrolle bleibt auch nach dem sichtbaren Ende der Werbung eingeplant."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Lies den Plan als Person, die nach ihm arbeiten soll.","steps":"Prüfe je Laden, was nach deiner bisherigen Entscheidung noch abgesichert werden muss.","example":"Ein Freigabevermerk hilft wenig, wenn die folgende Meldung überhaupt keiner zuständigen Person zugeordnet wurde.","c":3,"sourceRefs":["M2","M3","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Das Ergebnis zurückmelden","scene":"Übungsvariante: Am Montag nach der Aktion liegen beide Stückzahlen vor. Jan bittet um eine kurze, nachvollziehbare Rückmeldung zu euren Entscheidungen.","ask":"Wie schließt du die Kette ab?","options":["Du zeigst pro Laden Ausgangsmenge, Zielmenge und Aktionsmenge und erklärst, welche Schlüsse der Vergleich trägt.","Du besprichst den Zielvergleich mit beiden Ladenleitungen und fragst, was bei Beratung und Orientierung aus ihrer Sicht gut lief.","Du prüfst, ob beide Meldungen die vereinbarten Artikel und Tage umfassen, und legst Plan und Zahlen gemeinsam ab.","Du hältst im Ergebnis fest, welche Aussage am Kassenwert belegt ist und welche nach einer weiteren Beobachtung fragt.","Du lässt die Partner eine konkrete Verbesserung für die nächste Aktion vereinbaren und legst fest, wer sie prüft.","Du dokumentierst die erreichte oder verfehlte Zielgröße und ergänzt eine offene Zuständigkeit für die nächste Planung."],"consequences":["Der Vergleich je Standort zeigt verständlich, ob die vereinbarte Zielgröße erreicht wurde.","Die Beteiligten verbinden ihre Erfahrungen mit der gemeinsamen Zahl, ohne Einzelbeobachtungen als Stückzahlen auszugeben.","Die nächste Auswertung kann auf vollständige und vergleichbare Unterlagen zurückgreifen.","Du trennst den belegten Befund von einer noch offenen Erklärung.","Die Rückmeldung wird als gemeinsam abgestimmter nächster Schritt weitergeführt.","Das Ergebnis geht mit einem eindeutigen Auftrag in die nächste Planungsrunde ein."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Führe den Schwerpunkt aus deiner bisherigen Kette bis in die Rückmeldung weiter.","steps":"Schaue kurz auf deine vorangehende Entscheidung. Benenne, welche Information du im Ergebnis wieder aufgreifst.","example":"Eine gute Rückmeldung trennt das gemessene Ergebnis von der Frage, welchen Anteil die Werbung daran hatte.","c":0,"sourceRefs":["M2","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Bekannte Empfänger","scene":"Block in Aurich möchte auf den Beratungsbesuch nach der Arbeit aufmerksam machen.","ask":"Woran erkennt man, dass die E-Mail hier ein passender Weg sein kann?","options":["Sie kann nur von Personen im Laden geöffnet werden.","Sie ist für den Eingang der Bike Arena bestimmt.","Die Menschen können den Hinweis vor dem Besuch lesen.","Sie ersetzt die Beratung vor Ort.","Sie zeigt, wie viele Beratungen schon stattgefunden haben.","Sie erreicht Menschen, die schon Kontakt zu Block hatten."],"answer":[2,5],"why":"Der Newsletter erreicht bekannte Kundschaft vor dem Besuch. Die persönliche Beratung findet weiterhin vor Ort statt.","hint":"Denke an den Weg von der Nachricht bis zum Ladenbesuch.","steps":"Suche eine Antwort zur Empfängergruppe und eine zum Zeitpunkt.","example":"Eine Abonnentin kann eine E-Mail morgens lesen und nach Feierabend vorbeikommen.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Hinweis für den Heimweg","scene":"Übungsvariante: Block will Menschen mit Alltagsrad vor dem Heimweg erreichen. Viele dieser Kundinnen und Kunden haben den Newsletter abonniert.","ask":"Was sollte bei der Auswahl des Werbeträgers berücksichtigt werden?","options":["Der bekannte Empfängerkreis ist ein Grund für den Newsletter.","Im Newsletter kann Block zur Beratung vor Ort einladen.","Damit der Kanal passt, muss die Werbung von einem Netzteil handeln.","Ein Versand vor dem üblichen Besuch erleichtert die Planung.","Ein Hauptgangschild in Leer ist wegen des identischen Themas genauso direkt.","Den Beitrag erst veröffentlichen, wenn die Beratung abgeschlossen ist."],"answer":[0,1,3],"why":"Zum Ziel passt ein Hinweis, der bekannte Alltagsradelnde vor dem Besuch erreicht und ihnen einen klaren Beratungsanlass gibt.","hint":"Vergleiche die Empfangssituation mit der gewünschten Handlung.","steps":"Entscheide für jede Aussage, ob sie Zeitpunkt, Zielgruppe oder Ort der Handlung passend verbindet.","example":"Der Zeitpunkt der Ansprache kann vor der Handlung liegen, die sie auslösen soll.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Kundschaft am Wochenende","scene":"Die Bike Arena in Leer erwartet im Fall vor allem am Samstag Familien.","ask":"Welche Orte erreichen diese Menschen, wenn sie bereits ins Geschäft kommen?","options":["Eine interne Liste für Beratungstermine.","Ein Hinweisschild am Hauptgang.","Das Freigabeformular der Druckerei.","Ein Newsletter von Block in Aurich.","Der Aufsteller am Eingang.","Eine Auswertung am Montag nach der Aktion."],"answer":[1,4],"why":"Eingang und Hauptgang liegen auf Wegen der Kundschaft im Laden. Dort kann Werbung Menschen beim Einkauf erreichen.","hint":"Suche nach Stellen, an denen die Kundschaft vorbeiläuft.","steps":"Trenne Werbung im Laden von internen Arbeitsschritten.","example":"Wer einen Laden betritt, kann einen Eingangshinweis sehen, bevor er Produkte auswählt.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Eine Familie findet Zubehör","scene":"Übungsvariante: Eine Familie kommt am Samstag ohne vorherigen Kontakt in die Bike Arena. Sie sucht selbst Fahrradzubehör.","ask":"Was hilft der Familie und passt zu den vorhandenen Werbeplätzen?","options":["Ein gut sichtbarer Hinweis beim Betreten des Ladens.","Eine Nachricht, die nur Stammkundschaft von Block erhält.","Ein Hinweis auf die Aktionsfläche, an der die Familie selbst auswählt.","Nur eine Produktliste im Postfach der Ladenleitung.","Ein Hinweisschild dort, wo viele Menschen durch den Hauptgang laufen.","Der Plan, die Stückzahlmeldungen nach Geschäftsschluss auszuhängen."],"answer":[0,2,4],"why":"Familien können am Eingang oder Hauptgang erreicht und an die Auswahlfläche geführt werden. Eine interne Nachricht erreicht diese Einkaufssituation nicht.","hint":"Stell dir den Weg vom Eingang zum Produkt vor.","steps":"Wähle sichtbare Hinweise auf diesem Weg. Prüfe anschließend, was die Familie am Ziel tun kann.","example":"Ein Schild mit einem konkreten Ziel hilft auch Personen ohne vorherige Nachricht.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Aushang im Fenster","scene":"Bei Block kann ein gedruckter Aushang im Schaufenster hängen.","ask":"Wie werden Platz und gestaltete Werbung richtig bezeichnet?","options":["Der Aushang ist der Werbeträger.","Die Druckfreigabe ist die Werbebotschaft.","Die Öffnungszeit ist das Werbemittel.","Das Schaufenster ist der Werbeträger.","Die Verkaufszahl ist der Werbeträger.","Der gedruckte Aushang ist das Werbemittel."],"answer":[3,5],"why":"Das Schaufenster trägt oder zeigt die Werbung. Der gestaltete Aushang ist die sichtbare Werbefassung.","hint":"Du kannst den Aushang aus dem Fenster nehmen. Was bleibt?","steps":"Unterscheide den Ort vom gestalteten Inhalt und ordne beide Begriffe zu.","example":"Eine freie Wand ist ein Werbeplatz. Ein Poster ist das gestaltete Werbemittel.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Versand und Inhalt auseinanderhalten","scene":"Übungsvariante: Sarah liefert eine Datei, Block setzt daraus eine Anzeige in den eigenen E-Mail-Newsletter. Die Bike Arena nutzt einen Platz am Hauptgang mit einem gedruckten Hinweisschild.","ask":"Welche Zuordnungen stimmen?","options":["Der Newsletter dient als Werbeträger.","Der fertige Werbebeitrag im Newsletter ist ein Werbemittel.","Der Werbeplatz am Hauptgang trägt die Werbung, das gedruckte Hinweisschild ist das Werbemittel.","Die Druckfreigabe macht das Schild zum Werbeträger.","Der Hauptgang ist das fertige Schild.","Die E-Mail-Verteilerliste ist das fertig gestaltete Werbemittel."],"answer":[0,1,2],"why":"Der Beitrag und das Hinweisschild sind gestaltete Werbemittel. Newsletter und Platz am Hauptgang machen sie für die Kundschaft sichtbar.","hint":"Prüfe zuerst, was Sarah oder ein Laden tatsächlich gestaltet.","steps":"Stelle dir die fertige Werbung einmal mit und einmal ohne ihren Platz vor.","example":"Ein Beitrag kann technisch vom Newsletter getrennt werden, obwohl Kundschaft ihn erst über den Newsletter erhält.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Messbares Ziel ergänzen","scene":"Im Entwurf steht „Wir wollen in der Aktionswoche mehr Aktionsartikel verkaufen“.","ask":"Welche Angaben machen aus dem Wunsch ein überprüfbares Ziel?","options":["Die Titel der Werbemittel.","Das Kürzel aus der E-Mail-Signatur.","Der Name der Druckerei.","Die Einheit „Stück aus dem Aktionssortiment“ ausdrücklich festhalten.","Eine konkrete Zielmenge je Laden.","Die Farbe des Aufstellers."],"answer":[3,4],"why":"Die Aktionswoche ist schon genannt. Die genaue Stückzahl und ein klar abgegrenztes Sortiment machen feststellbar, ob das Ziel erreicht wurde.","hint":"Suche, welche Zahlen fehlen.","steps":"Prüfe, ob die Aussagen klären, was und wie viel gemessen wird.","example":"„40 Stück“ beantwortet die Frage nach der Menge. „Mehr“ allein tut das nicht.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M6"]},{"title":"Ziel in eine Planzeile schreiben","scene":"Übungsvariante: Die Partner vereinbaren für die Aktionswoche mindestens 45 verkaufte Aktionsartikel bei Block und mindestens 67 bei der Bike Arena. M2 nennt die Stückzahlen der früheren Vergleichswoche.","ask":"Welche Einträge beschreiben das überprüfbare Ziel oder dokumentieren die passende Ausgangslage?","options":["Beide Läden sollen Kunden mit passenden Werbemitteln erreichen.","45 und 67 Stück wollen wir demnächst erreichen.","Bis Mittwoch sollen zwei Werbefassungen vorliegen.","Die Partner bemühen sich um möglichst viele Beratungen.","Block soll in der Aktionswoche von Dienstag bis Samstag mindestens 45 Stück aus dem Aktionssortiment verkaufen, die Bike Arena mindestens 67 Stück.","Ausgangslage aus der Vergleichswoche: 40 verkaufte Stücke des Aktionssortiments bei Block und 60 bei der Bike Arena."],"answer":[4,5],"why":"Das Ziel nennt Kennzahl, Zielwerte je Laden und Messzeitraum. Die 40 und 60 Stück aus M2 sind Ausgangswerte. Mit ihnen lässt sich die Veränderung je Standort berechnen.","hint":"Trenne die angestrebte Menge von der Menge, die beide Läden früher verkauft haben.","steps":"Markiere im Ziel, was, wie viel und wann gezählt wird. Vergleiche die Ausgangswerte anschließend mit M2.","example":"Ein früher Freigabetermin ist eine wichtige Frist, aber kein verkaufsbezogenes Werbeziel.","sourceRefs":["M2","M5","M6"],"id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Datenzeilen vergleichen","scene":"Übungsvariante: Blocks Liste enthält 17 Beratungen und 24 verkaufte Stücke aus dem Aktionssortiment. Die Bike Arena meldet für dieselbe Woche keine Beratungszahl und 39 verkaufte Stücke aus dem Aktionssortiment.","ask":"Welche Einträge passen in eine gemeinsame Tabelle für den Verkaufsvergleich?","options":["Block: 17. Bike Arena: 39. Beide Zahlen stehen in der gemeinsamen Verkaufszeile.","Block: 24. Bike Arena: 39. Beide Zahlen stehen in der Zeile „Verkaufte Stücke“.","Bike Arena: 0 Beratungen. Ohne Meldung hat sicher keine Beratung stattgefunden.","Block: 41 verkaufte Stücke. Hierfür werden 17 und 24 zusammengezählt.","Für die Verkaufszeile zu beiden Zahlen das gleiche Sortiment und dieselbe Aktionswoche nennen.","Block und Bike Arena können in dieser Verkaufszeile nur verglichen werden, wenn sie gleich viele Beratungen melden."],"answer":[1,4],"why":"24 und 39 bezeichnen verkaufte Stücke des gleichen Sortiments im gleichen Zeitraum. Die 17 Beratungen beantworten eine andere Frage. Eine fehlende Zahl bedeutet nicht null.","hint":"Suche eine Datenzeile, in der für beide Läden dieselbe Einheit steht.","steps":"Ordne die drei Zahlen den Zeilen Beratungen und verkaufte Stücke zu. Prüfe bei jeder Zeile, ob beide Werte vorliegen.","example":"Ein offenes Feld bedeutet, dass keine Zahl vorliegt. Eine eingetragene Null ist ein Messergebnis.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Zielvergleich oder Standortfrage?","scene":"Übungsvariante: Ein Laden meldet 16 Beratungen und 31 verkaufte Stücke aus dem Aktionssortiment. Der andere hat 38 Stück aus dem Aktionssortiment verkauft. Er kann keine zuverlässige Beratungszahl nennen.","ask":"Welche Daten eignen sich für die gemeinsame Auswertung oder als getrennte Zusatzangabe eines Standorts?","options":["31 und 38 verkaufte Aktionsartikel, wenn beide, wie vereinbart, in der Aktionswoche zählen.","Die 16 Beratungen als Ersatz für die dort verfügbaren Verkaufszahlen.","Die 16 Beratungen zusätzlich zur Einordnung des ersten Standorts.","Die beiden Zahlen einfach als Prozentsatz zusammen ausweisen.","Ein gemeinsamer Zielwert aus 16 Beratungen und 38 verkauften Stücken.","Die fehlende Beratungszahl als glaubwürdigen Schätzwert nachtragen."],"answer":[0,2],"why":"31 und 38 sind Werte derselben Kennzahl. Die 16 Beratungen beantworten eine andere, nur am ersten Standort überprüfbare Frage.","hint":"Achte auf Tätigkeit und Zeitraum hinter jeder Zahl.","steps":"Ordne die drei Zahlen der Beratung oder dem Stückverkauf zu. Entscheide, welche Werte beide Läden messen und welcher Wert nur als Zusatzangabe dienen kann.","example":"Einheitliche Messung ermöglicht Vergleich. Zusätzliche Angaben können eine eigene Standortfrage beantworten.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Die Vergleichswoche lesen","scene":"Vor der Aktion braucht Jan Ausgangswerte für die beiden Läden.","ask":"Welche Paarungen stehen in M2 für die Vergleichswoche?","options":["Bike Arena: 40 verkaufte Stücke.","Bike Arena: 60 Newsletter-Abonnements.","Bike Arena: 60 verkaufte Stücke des Aktionssortiments.","Block: 40 verkaufte Stücke des Aktionssortiments.","Block: 60 Beratungen.","40 und 60 Stück aus der bereits beendeten Aktionswoche."],"answer":[2,3],"why":"M2 nennt für die frühere Woche 40 Stück bei Block und 60 bei der Bike Arena. Beide Angaben beziehen sich auf dieselbe Produktgruppe.","hint":"Achte darauf, welcher Standort zuerst genannt wird.","steps":"Schreib zu jeder Zahl Standort, Einheit und Zeitraum.","example":"Die Einheit „Stück“ unterscheidet den Ausgangswert von einer Beratungszahl.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Vergleichsdaten passend auswählen","scene":"Übungsvariante: Jan hat zwei alte Berichte. Bericht A umfasst dieselben Verkaufstage und Aktionsartikel, Bericht B enthält alle Zubehörverkäufe einschließlich eines zusätzlichen Sonntags.","ask":"Welche Schritte machen den Vergleich brauchbar?","options":["Statt der Berichte die geplanten Zielwerte als bereits verkaufte Menge eintragen.","Die Ausgangswerte getrennt je Geschäft dokumentieren.","Die Summe aus A und B einfach als Ausgangswert eintragen.","Einheit, Produktgruppe und Öffnungstage vor dem Vergleich kontrollieren.","Bericht B allein nutzen, weil eine längere Woche besser zu vergleichen ist.","Bericht A als Ausgangspunkt wählen, wenn die Erfassung zur Aktionswoche passt."],"answer":[1,3,5],"why":"Vergleichbar sind Berichte mit möglichst ähnlichen Bedingungen. Getrennte Werte je Standort erlauben, seine Entwicklung nachzuvollziehen.","hint":"Vergleiche Tage, Artikel und Standorte.","steps":"Schreibe eine kurze Liste der Bedingungen, die in beiden Zeiträumen übereinstimmen sollen.","example":"Ein zusätzlicher Öffnungstag kann Verkäufe erhöhen, auch wenn sich sonst nichts geändert hat.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Blocks Freigabe wiederfinden","scene":"Block nutzt in Aurich den E-Mail-Newsletter.","ask":"Welche Schritte müssen beim Versand vorbereitet werden?","options":["Der Laden plant den Versand am Montag um 8 Uhr.","Der Newsletter geht am Mittwoch um 16 Uhr an die Druckerei.","Die Druckerei liefert den Newsletter am Donnerstag der Aktionswoche aus.","Jan meldet den Newsletter erst nach der Verkaufsauswertung an.","Die Ladenleitung prüft und genehmigt den Text bis Donnerstag um 12 Uhr in der Vorbereitungswoche.","Block verschickt ihn am Freitag, wenn der Eingang aufgestellt wird."],"answer":[0,4],"why":"Block braucht vor dem Versand die Freigabe seiner Ladenleitung. Der Newsletter geht am Montag um 8 Uhr vor Verkaufsstart raus.","hint":"Schau in M3 nur auf den Newsletter.","steps":"Lies zuerst die Freigabe und danach den Einsatztermin.","example":"Eine Donnerstagsfreigabe ist ein Arbeitsschritt vor dem Montagsversand.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Newsletter bei enger Übergabe","scene":"Übungsvariante: Blocks Ladenleitung kann den Newsletter vor Freitag nur noch am Donnerstagvormittag prüfen. Der Werbebeitrag liegt am Mittwoch bereits vor.","ask":"Welche Verabredungen sichern den geplanten Einsatz?","options":["Den Newsletter drucken und in Leer am Eingang anbringen.","Den freigegebenen Beitrag für Montag um 8 Uhr im Newsletter einplanen.","Am Donnerstag eine Prüfung vor der Freigabefrist um 12 Uhr vereinbaren.","Der Ladenleitung die aktuelle Fassung rechtzeitig am Vormittag vorlegen.","Die Rückmeldung erst am Montag um 8 Uhr erfragen.","Den Versand vor der Prüfung auslösen."],"answer":[1,2,3],"why":"Der Entwurf wird rechtzeitig geprüft und von Block freigegeben. Erst die geprüfte Fassung wird für den vereinbarten Zeitpunkt eingeplant.","hint":"Suche das Zeitfenster für Prüfung und Zustimmung.","steps":"Sortiere Entwurf, Prüfung, Freigabe und Versand chronologisch.","example":"Ein fertiger Entwurf nützt dem Versand wenig, wenn die prüfende Person ihn erst nach der Frist erhält.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Den Ablauf für den Eingang korrigieren","scene":"Übungsvariante: Am Eingang der Bike Arena soll ein Schild im Aufsteller stehen. Auf drei gemischten Karten steht: „Schild aufstellen → Druckerei liefert → Ladenleitung gibt den Druck frei“.","ask":"Welche Pfeile bringen die drei Schritte in die richtige Reihenfolge?","options":["Schild aufstellen → Ladenleitung gibt Druck frei.","Ladenleitung gibt Druck frei → Druckerei kann das Schild herstellen und liefern.","Druckerei liefert → Ladenleitung kann den Druckauftrag erst danach freigeben.","Schild aufstellen → Druckerei begann mit der Herstellung.","Druckerei liefert → Bike Arena stellt das gelieferte Schild am Eingang auf.","Die Druckerei genehmigt den Entwurf für die Bike Arena → Block stellt das Schild in Leer auf."],"answer":[1,4],"why":"Die Ladenleitung erlaubt den Druck. Danach stellt die Druckerei das Schild her und liefert es. Die Bike Arena kann erst dann das gelieferte Schild am Eingang aufstellen.","hint":"Was muss die Druckerei wissen, bevor sie herstellen kann?","steps":"Beginne mit der Freigabe. Lege dann die Karten nach der Frage „Was muss schon erledigt sein?“","example":"Etwas vor Ort aufzubauen setzt voraus, dass das Material schon angekommen ist.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Terminfehler auf dem Laufzettel","scene":"Übungsvariante: Auf dem Laufzettel für den Eingangsaufsteller in Leer stehen zwei falsche Angaben: „Späteste Lieferung durch die Druckerei: Dienstag der Aktionswoche“ und „Sichtbarer Einsatz am Eingang: ab Donnerstag der Aktionswoche“. Die Freigabefrist für den Druck fehlt.","ask":"Welche Einträge müssen korrigiert oder ergänzt werden?","options":["Die Druckerei baut den Aufsteller am Dienstag beim Laden auf.","Die Lieferung ist bis Donnerstag der Aktionswoche vorgesehen.","Die Ladenleitung erteilt der Druckerei bis Mittwoch um 16 Uhr die Freigabe.","Die Freigabe erfolgt durch Block, weil auch dort Werbung geplant ist.","Die Bike Arena kann die Druckfreigabe erst am Freitag beim Einsatz erteilen.","Die Bike Arena stellt das Schild ab Freitag der Aktionswoche auf."],"answer":[1,2,5],"why":"Die Ladenleitung gibt den Druck bis Mittwoch, 16 Uhr, in der Vorbereitungswoche frei. Die Druckerei liefert bis Donnerstag der Aktionswoche. Die Bike Arena stellt das Schild ab Freitag der Aktionswoche auf.","hint":"Trenne die Vorbereitungswoche von der Aktionswoche.","steps":"Lege die Schritte auf zwei Zeitachsen und ordne den ausführenden Betrieb zu.","example":"Eine Lieferung am Donnerstag ist noch kein Einsatz; das Schild kann einen Tag später aufgestellt werden.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Wer kooperiert mit wem?","scene":"Global Bike liefert beiden Läden die Unterlagen für die Frühjahrsaktion.","ask":"Welche Merkmale zeigen, dass die Unternehmen gemeinsam werben?","options":["Die Partner stimmen die gemeinsame Aktion und die Aufgaben ab.","Die Druckerei legt fest, wie viele Artikel verkauft werden sollen.","Alle Geschäfte prüfen völlig eigene Aktionen und Ziele.","Die jeweiligen Ladenleitungen geben ihre Fassungen frei.","Jeder Laden veröffentlicht zum gleichen Uhrzeitpunkt dasselbe Werbemittel.","Global Bike braucht die beiden Läden bei der Vorbereitung nicht."],"answer":[0,3],"why":"Kooperative Werbung verbindet ein gemeinsames Ziel mit verteilten Aufgaben. Unterschiedliche Werbemittel können zum selben Vorhaben beitragen.","hint":"Suche Abstimmung und Beiträge verschiedener Unternehmen.","steps":"Prüfe, was gemeinsam vereinbart und was pro Laden erledigt wird.","example":"Zwei Partner können dieselbe Aktion mit verschiedenen Kanälen bekannt machen.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Gleiche Kampagne mit verschiedenen Beiträgen","scene":"Übungsvariante: Eine dritte Filiale schlägt vor, die vorhandene Botschaft zu nutzen und zusätzlich einen Aushang vor Ort zu gestalten.","ask":"Welche Abmachungen machen diesen Vorschlag zu einem sinnvollen Beitrag zur Kooperation?","options":["Die Filiale bestellt selbst eine völlig andere Aktion und führt dieselben Zahlen an.","Die Läden müssen jede Schriftgröße und jeden Werbeplatz gleich wählen.","Die Filiale stimmt das gemeinsame Ziel mit den anderen Beteiligten ab.","Die Aushanggestaltung ersetzt die Abstimmung mit den übrigen Beteiligten.","Global Bike und die Filiale legen fest, wer welche Unterlagen und Rückmeldungen liefert.","Sie übernimmt klar die Freigabe und den Einsatz ihres eigenen Aushangs."],"answer":[2,4,5],"why":"Die Beteiligten tragen unterschiedliche Maßnahmen bei und einigen sich auf gemeinsames Ziel, klare Aufgaben und Rückmeldung. Die gleichen Formate sind dabei nicht erforderlich.","hint":"Prüfe, ob der neue Beitrag mit dem gemeinsamen Vorhaben verbunden ist.","steps":"Suche Vereinbarungen, in denen Ziel, Rolle und Übergaben erkennbar sind.","example":"Ein individueller Aushang kann Teil einer gemeinsamen Aktion sein, wenn die übrigen Absprachen dazu passen.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Freigabe im Kalender","scene":"Das Schild für die Bike Arena muss vor dem Druck genehmigt sein. Kundschaft sieht es erst später am Eingang.","ask":"Welche Begriffe passen zu diesen Schritten?","options":["Meldetermin und Freigabefrist bezeichnen immer denselben Tag.","Die späteste Zustimmung ist die Freigabefrist.","Die Kassenmeldung ist die Freigabefrist.","Das Aufstellen für Kundschaft markiert den Einsatz.","Die Lieferfrist ist automatisch der Verkaufsstart.","Der Einsatztermin ist die letzte Gelegenheit zum Drucken."],"answer":[1,3],"why":"Die Freigabefrist begrenzt die Zustimmung. Der Einsatztermin sagt, ab wann die Werbung sichtbar ist. Herstellung und Lieferung liegen dazwischen.","hint":"Frag, ob es um eine Unterschrift oder um sichtbare Werbung geht.","steps":"Ordne jeden Begriff einem beobachtbaren Ereignis zu.","example":"Ein Schild kann schon geliefert sein, ohne im Laden zu stehen.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Zwei Termine sauber notieren","scene":"Übungsvariante: Ein Laden kann einen Aushang bis 10 Uhr genehmigen und ab 15 Uhr ins Fenster hängen. Der Ausdruck findet dazwischen statt.","ask":"Welche Planzeile trennt Freigabe und Einsatz sinnvoll?","options":["Den Ausdruck um 15 Uhr als Freigabefrist bezeichnen.","Die beiden Angaben zu einem Termin „irgendwann heute“ zusammenfassen.","Den Aushang ab 15 Uhr als sichtbaren Einsatz festhalten.","Bei Aufstellung um 15 Uhr die Freigabe gleichzeitig nachholen.","Die Zustimmung bis 10 Uhr als Freigabe festhalten.","Den Zeitraum bis 10 Uhr als Dauer der Werbung festhalten."],"answer":[2,4],"why":"Die Genehmigung um 10 Uhr ermöglicht den Ausdruck. Ab 15 Uhr wird der Aushang eingesetzt und kann gesehen werden.","hint":"Achte darauf, wann Kundschaft die Werbung erstmals sehen kann.","steps":"Schreibe zu jeder Uhrzeit den dazugehörigen Arbeitsschritt.","example":"„Bis“ begrenzt eine Frist. „Ab“ gibt häufig den Beginn eines Einsatzes an.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Aufgaben im Team nachsehen","scene":"Die Aktion braucht Daten, Koordination und Zustimmung.","ask":"Welche Zuordnungen nennt M3?","options":["Sarah stellt Produktangaben und Bilder bereit.","Jan stimmt die Absprachen bei Global Bike ab.","Die Druckerei gibt den Newsletter von Block frei.","Die Verkaufsmeldung der Bike Arena wird von Sarah an der Kasse erfasst.","Jede Ladenleitung prüft und genehmigt ihre Fassung.","Jan bringt beide Schilder selbst in den Läden an."],"answer":[0,1,4],"why":"Sarah bereitet die Unterlagen vor, Jan koordiniert und die jeweilige Ladenleitung genehmigt die Fassung für ihren Standort.","hint":"Ordne die drei Tätigkeiten Vorbereitung, Koordination und Freigabe zu.","steps":"Suche in M3 nach Personennamen und dem Bereich Ladenleitung.","example":"Die Person, die Bilder bereitstellt, muss den Platz im jeweiligen Geschäft nicht freigeben.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Entwürfe verbindlich übergeben","scene":"Übungsvariante: Am Mittwoch liegen um 14 Uhr je ein Entwurf für Block und für den Eingangsaufsteller in Leer vor.","ask":"Welche nächsten Schritte übernehmen die Handelspartner selbst?","options":["Die Ladenleitung in Leer prüft Platz und Angaben und meldet ihre Druckfreigabe an die Druckerei.","Jan entscheidet für beide Läden ohne Abstimmung, welches Werbemittel erscheint.","Sarah erklärt ihre Produktangaben ohne Rückmeldung automatisch für genehmigt.","Block prüft den eigenen Text und gibt ihn durch seine Ladenleitung frei.","Die Druckerei prüft für Block die Zielgruppe im Newsletter.","Block organisiert den Versand seines Newsletters selbst."],"answer":[0,3,5],"why":"Die Läden tragen die Verantwortung für ihre Fassungen. Der Entwurf stammt von Global Bike, Prüfung, Freigabe und Einsatz bleiben vor Ort zuständig.","hint":"Unterscheide, wer den Entwurf geschickt hat und wer ihn weiterverarbeitet.","steps":"Ordne jedem Standort Freigabe und späteren Einsatz zu.","example":"Eine fertig ausgearbeitete Datei bedeutet noch keine Zustimmung des Betriebs, der sie einsetzen soll.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Auswertung vorbereiten","scene":"Am Montag nach der Aktion sollen die Ergebnisse an Global Bike gehen.","ask":"Welche Unterlagen helfen beim Vergleich mit dem Ziel?","options":["Die Produktfotos für den Druckauftrag.","Die Uhrzeit, zu der Sarah die erste Datei hochgeladen hat.","Der Name aller Personen, die beraten wurden.","Die Angabe, zu welcher Woche beide Meldungen gehören.","Die Stückzahlen der Aktionsartikel je Laden.","Der vereinbarte Zielwert je Standort."],"answer":[3,4,5],"why":"Mit Zielwert, Aktionsstückzahl und Messwoche lässt sich der Zielerfolg prüfen. Andere Angaben helfen bei der Organisation, beantworten aber nicht diese Frage.","hint":"Überlege, welche Zeile Ziel und Ergebnis vergleichbar macht.","steps":"Suche die verbindlichen Planwerte und die dazu passenden Kassenwerte.","example":"Dass ein Entwurf rechtzeitig vorlag, sagt noch nicht, ob die angestrebten Stückzahlen verkauft wurden.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Einen lückenhaften Bericht verbessern","scene":"Übungsvariante: Die Rückmeldung aus Leer lautet nur „63 im Zubehör“. Block meldet „47 Stück aus dem Aktionssortiment, Dienstag bis Samstag der Aktionswoche“.","ask":"Wie macht ihr die Daten vergleichbar?","options":["Die getrennt bestätigten Ist-Zahlen mit den jeweiligen Zielen vergleichen.","Die 63 automatisch als Beratungen behandeln.","Für die 63 klären, ob dieselben Aktionsartikel erfasst wurden.","Für Leer Zeitraum und Einheit der Meldung bestätigen lassen.","Die Block-Meldung auf „47 im Zubehör“ kürzen, damit beide Texte ähnlich aussehen.","„Zubehör“ stillschweigend als genau das Aktionssortiment einstufen."],"answer":[0,2,3],"why":"Vor dem Vergleich müssen Produktgruppe, Einheit und Zeitraum derselben Messung entsprechen. Fehlende Angaben werden geklärt, statt sie zu erraten.","hint":"Ergänze die Angaben, die bei Block schon dabeistehen.","steps":"Prüfe, ob in beiden Zeilen Standort, Artikelgruppe, Stückzahl und Zeitraum eindeutig sind.","example":"Zwei ähnlich aussehende Zahlen sind erst dann vergleichbar, wenn dieselben Dinge gezählt wurden.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Alle Zielbausteine finden","scene":"Die Partner sammeln Vorschläge für ein gemeinsames Ziel.","ask":"Welche Angaben machen eine geplante Stückzahl später überprüfbar?","options":["Die Farbe des Aushangs.","Welche Aktionsartikel gezählt werden.","Welche Menge je Laden erreicht werden soll.","Der Name der Person, die den Aufsteller gestaltet.","An welchen Tagen der Absatz erfasst wird.","Die Reihenfolge der Entwürfe im Dateiordner."],"answer":[1,2,4],"why":"Verkaufte Artikel, festgelegter Zielwert und Messzeitraum sind die nötigen Bestandteile. Gestaltungsdetails gehören zur Maßnahme.","hint":"Denk an drei Fragen: Was, wie viel, wann?","steps":"Suche in jedem Vorschlag die Antwort auf mindestens eine dieser Fragen.","example":"„In der Aktionswoche mindestens 20 Stück des ausgewählten Zubehörs“ beantwortet alle drei Fragen.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Zielzahlen im Besprechungsprotokoll","scene":"Übungsvariante: Block will in der Aktionswoche von Dienstag bis Samstag mindestens 50 Stück aus dem Aktionssortiment verkaufen. Die Bike Arena plant mindestens 70 Stück.","ask":"Welche Protokolleinträge halten die Abmachung vollständig fest oder helfen, sie nach der Aktion zu überprüfen?","options":["Mindestens 50 Stück bei Block und 70 bei der Bike Arena, jeweils aus dem Aktionssortiment und in der Aktionswoche von Dienstag bis Samstag.","50 und 70, falls es klappt.","Die Druckfreigabe ist Mittwoch und wird sorgfältig geprüft.","Dienstag bis Samstag mehr beraten. Die Partner vereinbaren keinen Zielwert.","Wir wollen vor dem Wochenende mehr verkaufen.","Nach der Aktion melden beide Läden getrennt, wie viele Stücke sie von Dienstag bis Samstag aus dem Aktionssortiment verkauft haben."],"answer":[0,5],"why":"Die Zielvereinbarung legt Artikelgruppe, Stückzahlen und Zeitraum fest. Die beiden getrennten Verkaufsmeldungen liefern passende Ist-Werte für den Vergleich mit den jeweiligen Soll-Werten.","hint":"Unterscheide die vorher vereinbarten Mengen von den nachher gemessenen Mengen.","steps":"Prüfe zuerst, ob die Ziele eindeutig aufgeschrieben sind. Suche dann eine Meldung, die sich nach Standort, Stückzahl, Artikelgruppe und Zeitraum damit vergleichen lässt.","example":"Eine Meldung mit allen Zubehörverkäufen kann zu groß sein, wenn das Ziel nur bestimmte Aktionsartikel umfasst.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Zehn Prozent bei Block","scene":"Übungsvariante: Block hat 40 Stück als Ausgangswert und plant 10 % mehr.","ask":"Welche Schritte rechnen die Zielmenge richtig aus?","options":["40 und 10 einfach addieren.","40 Stück Ausgangsmenge und 4 Stück Zuwachs ergeben 44 Stück.","40 × 0,10 ergibt einen Zuwachs von 4 Stück.","40 durch 10 teilen und das Ergebnis als Zielmenge übernehmen.","4 Stück als Gesamtziel eintragen.","40 Stück ohne Veränderung als neues Ziel eintragen."],"answer":[1,2],"why":"Vier Stück sind der zusätzliche Absatz. Addiert zum Ausgangswert ergeben sie 44 Stück als Ziel.","hint":"Der Zuwachs ist kleiner als die ganze Zielmenge.","steps":"Berechne ein Zehntel der Ausgangsmenge und addiere es.","example":"Bei 20 Stück wären 10 % genau 2 zusätzliche Stück.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Fünftel mehr in beiden Läden","scene":"Übungsvariante: Die Läden planen 20 % mehr als in der Vergleichswoche mit 40 Stück bei Block und 60 in der Bike Arena.","ask":"Welche Zahlen gehören in den Plan?","options":["Bei beiden Läden gilt die Gesamtzielmenge 120 Stück als alleiniger Standortwert.","Block: Ziel 48 Stück.","Block: 60 Stück, weil 20 % immer 20 Stück sind.","Bike Arena: Ziel 68 Stück, weil beide gleich viele zusätzliche Stücke brauchen.","Zusätzlicher Absatz: bei Block 8, in der Bike Arena 12 Stück.","Bike Arena: Ziel 72 Stück."],"answer":[1,4,5],"why":"20 % von 40 sind 8 und von 60 sind es 12. Das ergibt Standortziele von 48 und 72 Stück.","hint":"Ein Fünftel wird für jede Ausgangsmenge getrennt bestimmt.","steps":"Teile 40 und 60 jeweils durch fünf. Addiere das Ergebnis zum passenden Standortwert.","example":"Derselbe prozentuale Anstieg muss nicht zu derselben Zahl zusätzlicher Verkäufe führen.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Den Werbeplatz am Zeitpunkt erkennen","scene":"Block möchte vor dem Besuch ansprechbar sein, die Bike Arena direkt am Eingang.","ask":"Welche vorhandenen Plätze passen am besten zu diesen Momenten?","options":["Die Nachricht im E-Mail-Newsletter erreicht Block-Kundschaft vor einem Besuch.","Das Eingangsschild erreicht ankommende Kundschaft bei der Bike Arena.","Der Hauptgang ist der einzige Ort unmittelbar vor dem Eintritt.","Die Erfolgskontrolle ist der erste passende Werbeplatz.","Ein nachträglicher Kassenbericht ersetzt beide Werbeträger.","Der Schaufensteraushang erreicht alle Stammkundinnen und Stammkunden von Block zu Hause."],"answer":[0,1],"why":"Der Newsletter wirkt schon vor dem Besuch. Das Eingangsschild ist unmittelbar beim Betreten sichtbar.","hint":"Denke an den Ort der Kundschaft beim Lesen.","steps":"Markiere „vor dem Besuch“ und „beim Eingang“ und ordne jeweils einen Werbeplatz zu.","example":"Dieselbe Botschaft wird durch eine Nachricht früher wahrgenommen als durch ein Schild im Laden.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Andere Kontaktpunkte auswählen","scene":"Übungsvariante: Block will diesmal vor allem Menschen erreichen, die am Schaufenster vorbeigehen. Die Bike Arena will in ihrem Laden früh in der Woche auf dem Hauptgang werben.","ask":"Welche Werbeplätze passen zu diesen genauen Absichten?","options":["Der Aushang in Aurich und das Schild in Leer wirken jeweils dort, wo die angesprochenen Menschen vorbeikommen.","Der Kassenbericht am Montag nach der Aktion.","Ein ausschließlich am Montag verschickter Newsletter als direktester Kontakt zu Vorbeigehenden.","Blocks Schaufensteraushang ab Dienstag.","Ein Hinweisschild der Bike Arena am Hauptgang ab Dienstag.","Der Aufsteller in Leer ab Freitag als erster Hinweis am Dienstag."],"answer":[0,3,4],"why":"Ein Aushang passt zu Menschen vor dem Auricher Schaufenster. Das Hauptgangschild ist in Leer schon am Dienstag zur Öffnung möglich.","hint":"Beachte Ort und ersten Einsatztag je Laden.","steps":"Vergleiche die Schaufenster- und Hauptgangzeilen in M3 mit den beiden Absichten.","example":"Ein Werbeplatz ist nur passend, wenn ihn die Zielgruppe zum gewünschten Zeitpunkt sehen kann.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Eine Lücke vor der Druckfreigabe","scene":"Übungsvariante: Auf dem Laufzettel für das Eingangsschild steht: „14 Uhr Entwurf da. Platz am Eingang geprüft. 16 Uhr Freigabe an die Druckerei“. Eine fachliche Prüfung fehlt.","ask":"Welche Ergänzungen machen die Freigabe des Schilds zuverlässiger?","options":["Die Druckerei soll erst beim Drucken entscheiden, ob die Produktangaben stimmen.","Die Ladenleitung gleicht die Aussagen über die Artikel mit den Produktangaben von Global Bike ab.","Die Stückzahlen der Aktionswoche als Ersatz für die Produktprüfung eintragen.","Vor einer Zustimmung Zeit für eine Korrektur einplanen, falls ein Fehler auffällt.","Das Schild sofort genehmigen, weil der freie Platz schon bestätigt ist.","Die Produktangaben im Newsletter von Block für das Schild in Leer ungeprüft übernehmen."],"answer":[1,3],"why":"Ein geeigneter Platz sagt nichts darüber, ob das Schild die Artikel richtig beschreibt. Deshalb prüft die Ladenleitung die Aussagen und lässt Fehler vor der Druckfreigabe korrigieren.","hint":"Suche, was neben dem Platz auf dem fertigen Schild geprüft werden muss.","steps":"Trenne die Prüfung des Werbeplatzes von der Prüfung des Textes. Setze die zweite Prüfung und mögliche Korrekturen vor die Zustimmung.","example":"Ein Aufsteller kann gut sichtbar stehen, obwohl im Schild eine falsche Artikelangabe enthalten ist.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Engen Vorlauf absichern","scene":"Übungsvariante: Die Ladenleitung in Leer hat Mittwoch von 14 bis 15 Uhr keine Zeit. Um 15 Uhr kann sie das Eingangsschild prüfen; die Druckerei benötigt die Freigabe bis 16 Uhr.","ask":"Welche Vorkehrungen sind sinnvoll?","options":["Den Termin des Aufstellens als neue Druckfreigabefrist angeben.","Vereinbaren, wer bis 16 Uhr die bestätigte Fassung an die Druckerei meldet.","Die Zeit bis 15 Uhr verstreichen lassen und erst dann prüfen, wo der Entwurf ist.","Vorher klären, wer bei einer Rückfrage zu den Produktangaben sofort erreichbar ist.","Den Entwurf bis 14 Uhr an die Ladenleitung schicken, damit er ab 15 Uhr bereitliegt.","Den Druck ohne Zustimmung schon beginnen lassen."],"answer":[1,3,4],"why":"Das kleine Zeitfenster kann gelingen, wenn Entwurf und Ansprechpartner bereitstehen und die Weitergabe der bestätigten Fassung vorab vereinbart ist.","hint":"Trenne die Zeit des Wartens von der Zeit, die ihr vorbereiten könnt.","steps":"Gehe den Ablauf rückwärts von 16 Uhr durch und finde jeden Schritt, der davor fertig sein muss.","example":"Ein vorab bereitgelegter Entwurf spart Zeit für die tatsächliche Prüfung.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Die Alternative im Laden","scene":"Die Bike Arena kann das Eingangsschild nicht mehr rechtzeitig drucken lassen. M3 nennt noch den Werbeplatz am Hauptgang.","ask":"Welche Arbeitsschritte gehören zu dieser Alternative?","options":["Die Bike Arena setzt es ab Dienstag zur Öffnung am Hauptgang ein.","Die Druckerei nutzt die verstrichene Mittwochsfreigabe.","Die Ladenleitung gibt das Hinweisschild bis Freitagmittag frei.","Der Hauptgang ist nur ab Freitag wie der Aufsteller nutzbar.","Der Aushang wird am Montag bei Block verschickt.","Die Bike Arena druckt das Hinweisschild selbst."],"answer":[0,2,5],"why":"Die Hauptganglösung braucht die Freigabe bis Freitag 12 Uhr und eigenen Druck. Sie kann ab Dienstag zur Öffnung sichtbar sein.","hint":"Lies die Hauptgangzeile genau, ohne die Daten vom Eingang zu übernehmen.","steps":"Ordne der Alternative Freigabe, Druck und Einsatz in dieser Reihenfolge zu.","example":"Zwei Schilder in demselben Laden können verschiedene Produktionswege haben.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Werbeträger wechseln, Ziel sichern","scene":"Übungsvariante: Die Partner haben Zielwerte bereits festgelegt. Nach verpasster Druckfreigabe wechselt Leer zum Hauptgang, Block bleibt beim Newsletter.","ask":"Welche Planänderungen passen?","options":["Den Newsletter von Block ganz streichen, weil Leer sein Schild wechselt.","Das gemeinsame Verkaufsziel sofort allein auf Beratung umstellen.","Die Standortbegründung ändern und erklären, wie das Schild am Hauptgang Kundschaft erreicht.","Das neue Hinweisschild samt Freigabe, eigenem Druck und Einsatzzeit für Leer eintragen.","Den gemeinsamen Zielvergleich nach verkauften Stückzahlen beibehalten.","Die alte Druckerei weiterhin als Ausführende des Hauptgangschildes eintragen."],"answer":[2,3,4],"why":"Der Wechsel betrifft Werbeplatz, Abläufe und die Begründung in Leer. Das gemeinsame Ziel und die Verkaufserfassung bleiben möglich.","hint":"Unterscheide den Werbeweg von der Messgröße.","steps":"Vergleiche alten und neuen Eintrag in Leer. Markiere alles, was sich für Block oder die Messung tatsächlich ändert.","example":"Ein anderer Werbeplatz kann auf dasselbe Verkaufsziel einzahlen.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Eine Zusage lesen","scene":"Jan will wissen, ob jeder Eintrag eine Person, eine Aufgabe und einen Termin nennt.","ask":"Welche Notizen sind vollständig genug zum Arbeiten?","options":["Blocks Ladenleitung gibt den Newslettertext am Donnerstag bis 12 Uhr frei.","Die Bike Arena meldet am Mittwoch bis 16 Uhr die Freigabe an die Druckerei.","Entwurf vorbereiten, sobald es passt.","Block kümmert sich möglichst schnell um die Aktion.","Bis Donnerstag passieren weitere Schritte.","Sarah schickt beide Entwürfe am Mittwoch bis 14 Uhr an die Läden."],"answer":[0,1,5],"why":"Die vollständigen Sätze geben jeweils an, wer was bis wann erledigt. So lässt sich eine Zusage auch von anderen Beteiligten nachverfolgen.","hint":"Prüfe jede Notiz mit drei Fragen.","steps":"Unterstreiche Person oder Betrieb, Tätigkeit und Zeitpunkt.","example":"„Druckerei“ allein ist kein Auftrag, solange Tätigkeit und Termin fehlen.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4","M5"]},{"title":"Notizen aus zwei Gesprächen zusammenführen","scene":"Übungsvariante: Im Gespräch zur Bike Arena fällt der Satz „Wir geben es am Freitag frei und bringen es am Dienstag an“. Gemeint ist das Hauptgangschild.","ask":"Welche Gesprächsnotizen machen die Zusage eindeutig und für Sarah verständlich?","options":["Im Protokoll den Hauptgang als Werbeplatz nennen, damit die Aussage nicht mit dem Eingangsschild verwechselt wird.","Druckerei: Schild spätestens Mittwoch um 16 Uhr aufstellen.","Block übernimmt Freigabe und Standortwahl in Leer.","Bike Arena: Hauptgangschild selbst drucken und ab Dienstag zur Öffnung anbringen.","Ladenleitung der Bike Arena: gedrucktes Hinweisschild für den Hauptgang bis Freitag 12 Uhr freigeben.","Freitag etwas freigeben; Dienstag vielleicht aufbauen."],"answer":[0,3,4],"why":"Die Zusage wird mit Standort, Werbeplatz, Verantwortlichen und Uhrzeit verständlich. Die Druckerei gehört zum Aufsteller, nicht zur hier gewählten Lösung.","hint":"Kläre besonders, wofür „es“ und „wir“ stehen.","steps":"Ersetze die unklaren Wörter durch Werbemittel und zuständige Stelle. Ergänze die Uhrzeit aus M3.","example":"Eine protokollierte Zusage kann später nur dienen, wenn klar bleibt, welches Schild gemeint ist.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4","M5"]},{"title":"Zusatzwert oder gemeinsames Ziel?","scene":"Beratung ist Block wichtig. Die Bike Arena möchte ihre Verkäufe prüfen.","ask":"Welche Abmachungen sind hilfreich?","options":["Die Zahl aus Block muss immer ohne Kennzeichnung mit der aus Leer addiert werden.","Wer Beratung zählt, darf im Werbeplan keine gemeinsame Zielzahl verwenden.","Die gemeinsame Kennzahl misst verkaufte Stücke der Aktionsartikel in beiden Läden.","Die Bike Arena soll Kundengespräche schätzen, auch wenn sie keine verlässlichen Daten hat.","Leer muss seinen Absatz als Beratungszahl umrechnen.","Block kann Beratungen daneben als eigenen Wert melden."],"answer":[2,5],"why":"Einheitliche Verkaufszahlen sichern den Vergleich. Block kann gleichzeitig einen eigenen Beratungswert verfolgen.","hint":"Welche Zahl ist nur für einen Standort verfügbar?","steps":"Teile das Protokoll in gemeinsame Messung und zusätzliche Standortmessung.","example":"Ein eigener Zusatzwert muss nicht als Messaufgabe auf den anderen Standort übertragen werden.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2"]},{"title":"Auf einen Interessenunterschied reagieren","scene":"Übungsvariante: Der gemeinsame Plan enthält Stückzahlen für beide Läden. Block möchte bei der Endbesprechung zusätzlich wissen, ob der Newsletter auf Beratung aufmerksam gemacht hat.","ask":"Was können die Beteiligten konkret vereinbaren?","options":["Die Gesprächszahl als zusätzliche Angabe in Blocks eigener Auswertung führen.","Bei der Besprechung ausdrücklich zwischen der Beratungsfrage und dem gemeinsam vereinbarten Werbeziel unterscheiden.","Die Meldungen 1:1 vergleichen, obwohl sie unterschiedliche Größen zählen.","Eine einzelne Beratung als sicheren Beweis für die gesamte Werbewirkung werten.","Die gemeinsamen Verkaufsergebnisse für beide weiterhin getrennt nach Standort auswerten.","Den Messwert aus Block durch die Beratungszahl ersetzen."],"answer":[0,1,4],"why":"Die Beteiligten können unterschiedliche Fragen stellen, solange jede Zahl zu ihrer Frage gehört. Der gemeinsame Verkaufsvergleich bleibt unverändert.","hint":"Überlege, welche Frage Block zusätzlich beantworten möchte.","steps":"Schreib zwei kurze Überschriften für den Bericht und ordne die Zahlen darunter ein.","example":"Ein Newsletter kann zu Beratungen einladen, während der gemeinsame Marktvergleich weiter mit Absatzwerten arbeitet.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2"]},{"title":"Das Schaufenster in M3 finden","scene":"Block will statt des Newsletters den gedruckten Aushang nutzen.","ask":"Welche Angaben passen genau zu dieser Variante?","options":["Einsatz am Montag um 8 Uhr als E-Mail.","Werbeträger Schaufenster, Werbemittel gedruckter Aushang.","Freigabe und Ausdruck bis Freitag um 14 Uhr in der Vorbereitungswoche.","Druckfreigabe durch die Bike Arena am Mittwoch.","Zeitpunkt der Erfolgskontrolle vor Beginn der Aktion.","Einsatz ab Dienstag zur Öffnung."],"answer":[1,2,5],"why":"Block gibt seinen Aushang bis Freitag um 14 Uhr frei, druckt ihn und bringt ihn für den Einsatz ab Dienstag an.","hint":"Lies nur die Zeile für das Schaufenster.","steps":"Ordne der richtigen Zeile erst Platz und Werbemittel, dann die beiden Termine zu.","example":"Freigabe und Ausdruck sind die Vorbereitung. Beim Anbringen wird die Werbung sichtbar.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Vom geplanten Versand zum Aushang","scene":"Übungsvariante: Block kann den Newsletter nicht einplanen. Ein Aushang im Schaufenster ist noch möglich, und Alltagsradelnde sollen beim Vorbeifahren auf Beratung aufmerksam werden.","ask":"Welche Planzeilen passen zur Änderung?","options":["Hauptgang der Bike Arena als Ort für Blocks Aushang festlegen.","Den Aushang als Nachweis für die spätere Zahl der Verkäufe behandeln.","Newsletter-Versand Montag um 8 Uhr unverändert als Einsatz des Schaufensters notieren.","Schaufenster als Ort und den gedruckten Aushang als Werbung eintragen.","Den Nutzen beim Vorbeifahren als Grund für die Wahl nennen.","Freigabe und Druck vor dem Anbringen einplanen und die Veröffentlichung auf Dienstag zur Öffnung setzen."],"answer":[3,4,5],"why":"Beim Wechsel passen sich Ort, Medium, Begründung und Zeitplan an. Das Schaufenster erreicht Menschen vor Ort, während der Newsletter sie vorher erreicht hätte.","hint":"Was ändert sich, wenn kein Versand stattfindet?","steps":"Ersetze alle Newsletter-spezifischen Schritte und begründe, wie die Kundschaft den neuen Hinweis wahrnimmt.","example":"Ein Hinweis im Fenster kann Menschen erreichen, die den Newsletter nicht abonniert haben.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Meldung mit der richtigen Einheit","scene":"Übungsvariante: Block hat 42 verkaufte Aktionsartikel und 19 Beratungen gezählt. Der gemeinsame Erfolgswert ist der Absatz in Stück.","ask":"Welche Angaben gehören in Blocks gemeinsame Meldung?","options":["42 als Anzahl aller Beratungen bezeichnen.","Den letzten geplanten Versandtermin anstelle des Werts nennen.","Den Laden und die zugehörige Aktionswoche nennen.","42 Stück verkaufte Aktionsartikel.","61, weil Verkäufe und Beratungen zusammengerechnet werden können.","19 Stück, weil Beratungen als Werbeerfolg zählen."],"answer":[2,3],"why":"42 ist die verabredete Absatzmenge. Für die Zuordnung werden Laden und Zeitraum genannt. Die Beratungen bleiben ein optionaler Zusatzwert.","hint":"Entscheide zuerst, was gemeinsamer Absatz bedeutet.","steps":"Finde die richtige Einheit und beschrifte die Meldung vollständig.","example":"Eine Beratungszahl kann zusätzlich danebenstehen, ohne den Verkaufswert zu verändern.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Bericht für Global Bike schreiben","scene":"Übungsvariante: Am Montag liegen zwei Tabellen vor. Bei Block stehen 51 Aktionsartikel und 29 Beratungen. Die Bike Arena hat 66 Aktionsartikel verkauft und zusätzlich 11 Reparaturen erfasst.","ask":"Welche Angaben übermittelt ihr für die gemeinsame Erfolgskontrolle?","options":["Die beiden Absatzmeldungen getrennt mit Standort angeben.","Bike Arena: 66 verkaufte Stücke des Aktionssortiments in der Aktionswoche.","Bike Arena: 77 Vorgänge als Zielwert.","Block: 80 aus Stückzahl und Beratungen.","Die frühere Woche rückwirkend mit 51 und 66 Stück notieren.","Block: 51 verkaufte Stücke des Aktionssortiments in der Aktionswoche."],"answer":[0,1,5],"why":"Aus beiden Tabellen werden nur die vergleichbaren Verkaufswerte der Aktionsartikel für den gemeinsamen Zielvergleich übernommen. Die anderen Größen bleiben separat.","hint":"Nicht jede Zahl im Bericht gehört zur vereinbarten Kennzahl.","steps":"Markiere zuerst die passenden Zahlen. Prüfe anschließend, welcher Zeitpunkt und Standort zu jeder Zahl mitgeteilt werden.","example":"Eine Reparatur ist ein Vorgang im Geschäft. Sie ist kein verkauftes Stück aus dem Aktionssortiment.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Ist oder Ziel?","scene":"Übungsvariante: Für Block gelten 40 Stück früher, 44 Stück als Ziel und 43 Stück als gemessener Wert.","ask":"Welche Aussagen stimmen?","options":["Das Ziel war um vier Stück geringer als das gemessene Ergebnis.","Block hat drei Stück mehr verkauft als in der Vergleichswoche.","Der höhere Absatz allein beweist, dass das vereinbarte Ziel erreicht wurde.","Es fehlt ein Stück bis zum gesetzten Ziel.","Block hat das Ziel erreicht, weil 43 über 40 liegt.","43 ist die Ausgangsmenge."],"answer":[1,3],"why":"43 liegt drei Stück über dem Ausgangswert und ein Stück unter dem Ziel. Steigerung und Zielerreichung sind verschiedene Aussagen.","hint":"Vergleiche den Ist-Wert zweimal.","steps":"Ziehe zuerst 40, dann 44 von 43 ab und deute beide Unterschiede.","example":"Ein Ergebnis kann sich verbessert haben und trotzdem unter dem vorher gesetzten Ziel liegen.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Zuwachs fair vergleichen","scene":"Übungsvariante: Beide Läden planen mindestens 20 % Zuwachs. Block steigt von 40 auf 47 Stück, die Bike Arena von 60 auf 72 Stück.","ask":"Welche Auswertung stimmt?","options":["Blocks Zielwert liegt bei 48 Stück; mit 47 fehlt ein Stück.","Die Bike Arena verfehlt das Ziel, weil ihr Vergleichswert höher ist.","Der passende Prozentwert ergibt sich je Laden aus seinem Zuwachs geteilt durch seine Ausgangsmenge.","Beide Läden erreichen das Ziel, weil beide Stückzahlen steigen.","Die Bike Arena erreicht mit 72 Stück genau 20 % Zuwachs.","Für beide genügt als Ziel eine Steigerung um sieben Stück."],"answer":[0,2,4],"why":"Block steigert um 7 Stück oder 17,5 %. Die Bike Arena steigert um 12 Stück oder 20 %. Nur Leer erreicht die 20-%-Vorgabe.","hint":"Berechne zuerst separat, wie viele Stücke 20 % ergeben.","steps":"Ermittle pro Laden Ziel und Ist. Vergleiche erst danach, wer das Ziel erreicht hat.","example":"Ein höherer Ausgangswert verlangt für denselben Prozentsatz mehr zusätzliche Stücke.","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Absatzanstieg beschreiben","scene":"In der Aktionswoche gehen mehr Aktionsartikel über die Kasse als in der Vergleichswoche.","ask":"Welche Aussagen hält der Vergleich allein aus?","options":["Der Newsletter war der alleinige Grund für den Anstieg.","Die Werbung hat sicher jeden zusätzlichen Verkauf verursacht.","Der Anstieg kann mit dem vereinbarten Zielwert verglichen werden.","Die Kundschaft hat das Schild eindeutig häufiger gesehen.","Weitere Einflüsse auf den Absatz sind möglich.","Die gemessene Absatzmenge ist gestiegen."],"answer":[2,4,5],"why":"Die Verkaufswerte tragen Aussagen zur Veränderung und zum Zielvergleich. Sie belegen für sich alleine keine bestimmte Ursache.","hint":"Trenne das Gemessene von seiner möglichen Erklärung.","steps":"Frage, ob etwas gezählt oder nur über die Wirkung vermutet wurde.","example":"An einem sonnigen Samstag können auch ohne neue Werbung mehr Menschen zum Laden kommen.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Mit einer zweiten Veränderung umgehen","scene":"Übungsvariante: Eine Woche ist viel sonniger als die Vergleichswoche. Gleichzeitig wird am Eingang in Leer geworben, und der Absatz steigt.","ask":"Welche Aussagen gehören in den Bericht?","options":["Vor einem größeren Schluss prüfen, ob Zeitraum, Öffnungstage und Sortiment vergleichbar waren.","Die Stückzahlen zeigen einen Anstieg gegenüber der Vergleichswoche.","Werbung als bewiesene einzige Ursache nennen, weil das Schild rechtzeitig aufgestellt wurde.","Wetter und Werbung sind mögliche Einflüsse. Aus der Stückzahl allein lässt sich ihr jeweiliger Anteil nicht ablesen.","Der Anstieg muss vollständig am Wetter liegen.","Nachträglich die Zielmenge so erhöhen, dass der Beobachtungszeitraum besser aussieht."],"answer":[0,1,3],"why":"Der Absatzanstieg lässt sich messen. Eine eindeutige Ursache lässt sich aus diesem Vergleich nicht ableiten, zumal sich eine weitere Bedingung verändert hat.","hint":"Suche alles, was sich zwischen den beiden Wochen geändert hat.","steps":"Trenne Ergebnis, mögliche Einflüsse und Belege für vergleichbare Daten.","example":"Bei mehreren gleichzeitigen Änderungen kann ein Vorher-nachher-Vergleich ihre einzelnen Wirkungen nicht sauber trennen.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Einen unvollständigen Plan lesen","scene":"Im Plan steht unter Block „Newsletter“ und unter der Bike Arena „Schild“; das gemeinsame Ziel ist bereits vollständig.","ask":"Welche Informationen machen den Plan tatsächlich ausführbar?","options":["Eine endgültige Erfolgsmeldung bereits vor Beginn der Aktion.","Wer den Entwurf an jedem Standort prüft und bis wann er freigibt.","Wann die Kundschaft den Hinweis sieht und wer ihn einsetzt.","Warum der jeweilige Werbeplatz zur Kundschaft passt.","Die Namen aller später beratenden Kundinnen und Kunden.","Die Lieblingsfarbe der beteiligten Personen."],"answer":[1,2,3],"why":"Ein ausführbarer Plan ergänzt Zuständigkeiten, Termine und den Grund für die Platzwahl. Das bereits vereinbarte Ziel bleibt bestehen.","hint":"Stell dir vor, du sollst morgen nach dieser Zeile handeln.","steps":"Suche fehlende Angaben zu Person, Frist, Einsatz und Wirkung am gewählten Ort.","example":"„Aushang“ beschreibt ein Werbemittel, aber noch nicht, wer es wann aushängt.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Plan auf Stolperstellen prüfen","scene":"Übungsvariante: Für Block steht „Aushang ab Dienstag“. Für Leer steht „Aufsteller am Eingang ab Freitag“. Bei beiden fehlen Druck und Freigabetermine.","ask":"Welche Ergänzungen sichern die zwei Maßnahmen?","options":["In Leer die erwartete Lieferung bis Donnerstag der Aktionswoche festhalten und das Aufstellen dem Laden zuordnen.","Leer: Eingangsschild selbst drucken und Freigabe am Freitag, 12 Uhr.","Die fehlende Freigabe nach dem Aufstellen vom Publikum einholen.","Blocks Aushang für Montag um 8 Uhr als E-Mail einplanen.","Block: Freigabe und Ausdruck bis Freitag, 14 Uhr, in der Vorbereitungswoche.","Bike Arena: Ladenleitung meldet Druckfreigabe bis Mittwoch, 16 Uhr, an die Druckerei."],"answer":[0,4,5],"why":"Der Plan ergänzt den richtigen Ablauf je Platz. Blocks Aushang und der externe Druck für den Aufsteller haben unterschiedliche Fristen und Zuständigkeiten.","hint":"Beide Maßnahmen sind gedruckt, aber die Herstellung läuft verschieden.","steps":"Prüfe in M3 genau die zwei gewählten Zeilen und übertrage die fehlenden Schritte.","example":"Eine interne Druckmöglichkeit braucht eventuell eine andere Frist als der Auftrag an eine Druckerei.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.5 · Eine gemeinsame Werbeaktion abstimmen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]}];
